window.APP_DATA_HOME = {"meta":{"csv":"afinidades_jinaclipv2_obrapoema_ligero.csv","rows":6550,"rows_matched":6550,"pintores":5,"poetas":5,"afinidades":6550},"simStats":{"max":0.415318,"min":0.06322,"q1":0.205142,"q2":0.240849,"q3":0.274946},"pintores":[{"dir":"amrita-sher-gil","name":"Amrita Sher-Gil","gender":"Mujer","period":"Modernismo, siglo XX","region":"India / Hungría","works":["01_three_girls.jpg","02_bride_toilet.jpg","03_hill_women.jpg","04_ancient_storyteller.jpg","05_sleeping_woman.jpg","06_hungarian_market_scene.jpg","07_child_bride.jpg","08_the_bride.jpg","09_woman_on_charpai.jpg","10_young_girls.jpg"],"topPoets":[{"name":"Ibarbourou, Juana de","value":0.247608,"best":0.339957},{"name":"Clark, Ben","value":0.233309,"best":0.313304},{"name":"Walt Whitman","value":0.229337,"best":0.30985}],"topPairs":[{"pintor":"amrita-sher-gil","obra":"05_sleeping_woman.jpg","poeta":"Ibarbourou, Juana de","sim":0.378734,"p":50},{"pintor":"amrita-sher-gil","obra":"06_hungarian_market_scene.jpg","poeta":"Ibarbourou, Juana de","sim":0.372218,"p":26},{"pintor":"amrita-sher-gil","obra":"09_woman_on_charpai.jpg","poeta":"Clark, Ben","sim":0.367279,"p":3}]},{"dir":"kusama","name":"Yayoi Kusama","gender":"Mujer","period":"Vanguardia contemporánea, siglos XX-XXI","region":"Japón","works":["01_waves-1953.jpg","02_woman-in-the-wind-1977.jpg","03_still-life-of-candlestick-1978.jpg","04_traveling-water-1980.jpg","05_dress-1982.jpg","06_flowers-1983.jpg","07_pumpkin-1983.jpg","08_dandelions-1985.jpg","09_yellow-pumpkin-1992.jpg","10_mushrooms-1995.jpg"],"topPoets":[{"name":"Ibarbourou, Juana de","value":0.245356,"best":0.323375},{"name":"Eduardo de la Cruz","value":0.237276,"best":0.316509},{"name":"Clark, Ben","value":0.197935,"best":0.296908}],"topPairs":[{"pintor":"kusama","obra":"04_traveling-water-1980.jpg","poeta":"Eduardo de la Cruz","sim":0.399952,"p":4},{"pintor":"kusama","obra":"04_traveling-water-1980.jpg","poeta":"Ibarbourou, Juana de","sim":0.379052,"p":45},{"pintor":"kusama","obra":"02_woman-in-the-wind-1977.jpg","poeta":"Clark, Ben","sim":0.360745,"p":14}]},{"dir":"monet","name":"Claude Monet","gender":"Hombre","period":"Impresionismo, siglos XIX-XX","region":"Francia","works":["01_impression_sunrise.jpg","02_water_lilies.jpg","03_woman_with_a_parasol.jpg","04_rouen_cathedral.jpg","05_poppy_field.jpg","06_japanese_bridge.jpg","07_saint_lazare_station.jpg","08_haystacks.jpg","09_san_giorgio_maggiore.jpg","10_dejeuner_sur_lherbe.jpg"],"topPoets":[{"name":"Ibarbourou, Juana de","value":0.246594,"best":0.36169},{"name":"Eduardo de la Cruz","value":0.239488,"best":0.319212},{"name":"Walt Whitman","value":0.222796,"best":0.303168}],"topPairs":[{"pintor":"monet","obra":"06_japanese_bridge.jpg","poeta":"Ibarbourou, Juana de","sim":0.39475,"p":51},{"pintor":"monet","obra":"05_poppy_field.jpg","poeta":"Ibarbourou, Juana de","sim":0.373404,"p":52},{"pintor":"monet","obra":"02_water_lilies.jpg","poeta":"Ibarbourou, Juana de","sim":0.371958,"p":51}]},{"dir":"okeeffe","name":"Georgia O’Keeffe","gender":"Mujer","period":"Modernismo, siglo XX","region":"Estados Unidos","works":["01_jimson_weed.jpg","02_black_iris.jpg","03_red_canna.jpg","04_rams_head_white_hollyhock.jpg","05_from_the_lake.jpg","06_sky_above_clouds.jpg","07_pelvis_with_the_distance.jpg","08_jack_in_the_pulpit_no_iv.jpg","09_cow_skull_red_white_blue.jpg","10_pink_dish_with_green_leaves.jpg"],"topPoets":[{"name":"Eduardo de la Cruz","value":0.273831,"best":0.372227},{"name":"Ibarbourou, Juana de","value":0.277288,"best":0.369743},{"name":"Clark, Ben","value":0.237621,"best":0.3425}],"topPairs":[{"pintor":"okeeffe","obra":"02_black_iris.jpg","poeta":"Eduardo de la Cruz","sim":0.415318,"p":3},{"pintor":"okeeffe","obra":"02_black_iris.jpg","poeta":"Clark, Ben","sim":0.4134,"p":4},{"pintor":"okeeffe","obra":"06_sky_above_clouds.jpg","poeta":"Eduardo de la Cruz","sim":0.410244,"p":9}]},{"dir":"sorolla","name":"Joaquín Sorolla","gender":"Hombre","period":"Luminismo, siglos XIX-XX","region":"España","works":["01_walk_beach.jpg","02_sad_inheritance.jpg","03_children_beach.jpg","04_white_slave_trade.jpg","05_strolling_seashore.jpg","06_fishermen_wives.jpg","07_wife_daughters_garden.jpg","08_the_lunch.jpg","09_sewing_sail.jpg","10_capuchin_church.jpg"],"topPoets":[{"name":"Eduardo de la Cruz","value":0.261431,"best":0.36618},{"name":"Ibarbourou, Juana de","value":0.256488,"best":0.364403},{"name":"Clark, Ben","value":0.249286,"best":0.325065}],"topPairs":[{"pintor":"sorolla","obra":"06_fishermen_wives.jpg","poeta":"Ibarbourou, Juana de","sim":0.397264,"p":35},{"pintor":"sorolla","obra":"03_children_beach.jpg","poeta":"Eduardo de la Cruz","sim":0.388465,"p":9},{"pintor":"sorolla","obra":"10_capuchin_church.jpg","poeta":"Ibarbourou, Juana de","sim":0.385576,"p":35}]}],"poetas":[{"name":"Clark, Ben","gender":"Hombre","period":"Poesía contemporánea, siglo XXI","region":"España","profile":null,"poems":[{"title":"Abdullah Samuels quema neumáticos en África.","year":"1984","text":"Abdullah Samuels quema neumáticos en África.\nLa nube es negra y densa y el poblado\ncierra (cuando es posible) sus ventanas.\nVende hierro.\nLleva así veinte años. Vende hierro.\nEl gobierno le ha dicho que no puede.\nLe ha dicho un periodista que no debe.\nLe ha dicho una ONG que se envenena,\nque envenena al poblado y a sus hijos.\nPero cada mañana Abdullah Samuels\nSe levanta temprano y busca ruedas.\nLleva así veinte años. Vende hierro."},{"title":"Acero inoxidable","year":"1984","text":"Acero inoxidable\n\nII\n\n\"Hijos de la bonanza\" nos llamaban:\nlos que no conocieron ni hambruna\nni las agudas larvas de estridencia\nchillando en el oído por las bombas.\nY cuando nuestras piernas tan delgadas\ncaían y sangraban porque el parque\nera de un hormigón armado y frío,\nse quedaban callados, observando\nnuestro llanto con un gesto de sorna.\n\nDebíamos vivir y dar las gracias\npor la ocre rozadura en la garganta\nque provocaba el aire al refugiarse.\nAgradecer las flechas de las nubes\ny que un fango lechoso a nuestros pies\n-en un último gesto agonizante-\nle mordiera las botas al progreso.\n¿Y cómo agradecerles la alegría?\nLa risa provocada por los hombres\ninocentes del mar\ncuando se encaminan hacia el río\ndispuestos a bañarse entre excrementos.\n\nTambién estaba el tedio\nde tener que explicarles a los niños\npalabras como pueblo indio, oso\npardo, ballena azul o lince ibérico.\nPero esto eran minucias, sacrificios\nen nada comparables con el sufrido\npor aquellos que ahora nos decían\n\"hijos de nuestra sangre\", tan severos.\n\nAunque a veces, es cierto, no era fácil,\nsimplemente intentamos ir viviendo.\nHaciendo caso omiso al comezón,\nal vacío que moraba en nosotros,\nhijos de la bonanza;\nlos hijos de los hijos de la ira,\nherederos de todos los despojos."},{"title":"Análisis sintacto","year":"1984","text":"IV\n\nPara Alberto de la Rocha\n\nHOY es domingo en casi todo el mundo.\nPero aquí, sin embargo, muere el miércoles,\nporque aquí la semana está borracha.\nY en su ebriedad, a veces, se le ocurren\ncosas estrafalarias, por ejemplo\nsupo que me dejaste un jueves frío,\nun día sin anécdotas –aparte\nde que tú me dejaras –.\nY desde entonces siempre que se aburre\n–y se aburre a menudo –\nse entretiene conmigo transformando\ncualquier mañana en miércoles, cualquier\nradiante día nuevo en aquel día\nen que sentí que el viento me miraba\nun poco compasivo, cuando vi\n–o eso me pareció – un gesto tuyo\nen aquella mujer del restaurante,\nla que no estaba sola.\nAquel miércoles\ntan largo y tan espeso que avanzaba\nhacia el último jueves de mi vida."},{"title":"Arte","year":"1984","text":"The disease had sharpened my senses\n\nEdgar Allan Poe\n\nLa doctora dibuja un corazón\n\nque no tiene forma de corazón.\n\nUn corazón enfermo, un vienés\n\nque baila mal el vals; la bomba atómica\n\ndel hombre que hay sentado a mi derecha.\n\nY juntos contemplamos al culpable.\n\nY juntos contemplamos a la víctima.\n\nSu representación (esto no es…).\n\nLa doctora dibuja un corazón\n\ny explica que la muerte llegará\n\naquí, o aquí, o aquí, o aquí\n\naunque puede que no, puede que no.\n\nLa doctora no sabe dibujar\n\npero traza sin miedo,\n\ny al hablar por teléfono sombrea\n\nlos bordes con un gesto de fastidio.\n\n«Ya lo decía Hipócrates…», nos dice,\n\ny antes de despedirnos guarda el esbozo enfermo\n\nen un cajón con llave."},{"title":"Carta a ariadna","year":"1984","text":"He aquí el engaño oscuro perpetrado,\ncarcoma negra hambrienta del deseo.\nSecreto a voces siempre que te veo,\nel beso infiel -tan fiel por otro lado.\n\nAquí le tienes vida, maniatado\ncon velas negras viene este Teseo\nculpable y solo. Aquí tienes al reo.\nY que ahora cuente al mundo su pecado:\n\nHe amado a otro rostro de amapolas,\n-adicto al opio nunca me di cuenta\nde que te estaba siendo infiel, a solas-.\n\nNo sirve ahora, amor, que yo te mienta;\ninfiel con tu recuerdo. Y las olas\nme abaten, regresando, ya, de Creta."},{"title":"Contra la literatura","year":"1984","text":"No hay nada más inútil que escribir. \nNada más dependiente que los libros. \nPero Alberto me llama y me pregunta \n\"¿Qué te está pareciendo mi novela?\"\nY yo le digo bien, salvo este punto \ny el momento en que dice esto y aquello \ny él escucha y anota y bien parece \nque aquí estamos haciendo algo importante. \n\nQuién pudiera vivir fuera de un libro, \njuntar en un hatillo las palabras \ny haciéndose a la mar decir \"Adiós; \nme voy para morir entre las fauces \nde una auténtica bestia, les regalo \nla curva de mi espalda, mis bolígrafos, \nel impreciso sueño de la gloria, \nla implacable derrota de mi olvido\"."},{"title":"Difusión simple","year":"1984","text":"Es extraño vivir, pertenecer\n\nal reducido mundo en movimiento.\n\nEs extraño vivir y beber zumos\n\nsobre arenas doradas en septiembre,\n\nhablar con el objeto de tu amor\n\n—porque vive también\n\na pesar de que sea algo improbable—.\n\nEs extraño vivir y caminar tranquilo\n\nsobre la piel reseca de los muertos,\n\nno estar con ellos, no ser uno de ellos\n\n—ni siquiera pensarlos todo el rato—.\n\nLos muertos son millones y uno solo;\n\nun cuerpo que se encoge. Nada más.\n\nEs sencillo entender su podredumbre\n\ny el engranaje simple de su olvido.\n\nPero existir. Estar. Desafiar\n\ncon tu sola presencia al gran ejército\n\nde la noche requiere un pensamiento\n\nabrumador, inútil, complicado.\n\nY sin embargo es fácil contentarse\n\ncon esta extraña dicha que es saberse\n\ny descubrirse día a día en el reflejo;\n\ncelebrar las miserias porque son\n\ncuando todo podría no ser más,\n\ny salir al tedioso mundo infame\n\narmado con el don de estar cansado\n\ny dolorido. Ser. Pertenecer\n\nal diminuto imperio del aliento."},{"title":"Hasta aquí hemos llegado","year":"1984","text":"Hasta aquí hemos llegado, sin apenas ayuda.\nSabemos quiénes somos, y ésta es nuestra ventaja.\nNo vivimos de sueños ni de lo que hemos sido\n(a pesar de haber sido más de lo que seremos).\nNuestra es la poesía si así lo convenimos,\ny todos los derechos que envuelven los deberes\nde aquellos que aceptamos. Sabemos protegernos.\nY si nos interrogan por Alá o por el Sabbath,\npor las verjas de Ceuta, por las fosas comunes,\npensarán que evitamos darles una respuesta.\nPero esto no es silencio sino lo que buscaban:\ntodos nuestros motivos, todo nuestro legado,\nun erial temerosos, un orgullo sin letra."},{"title":"Hoy","year":"1984","text":"Hoy\nHoy ha sido el primer día después.\nLas plazas se han llenado de mazorcas\ny la gente se acuerda, sin saber\nmuy bien por qué, del viaje de Colón,\ny todo es ancestral y todo es nuevo.\n\nHoy ha sido el primer día de todos.\nLos libros no leídos ya no importan,\nlos amores no amados son tan solo\nnombres que se arañaron en la arena,\nel recuerdo de un sueño en plena noche. \n\nHace falta volver a definir\nel Tiempo, renombrar\nlos días —siempre y cuando sean días\ny noches todavía separables—\nporque hoy ya nada puede ser lo mismo."},{"title":"La hora del paseo","year":"1984","text":"La hora del paseo\n\nUn hombre que ha salido con su perro,\nun hombre que ha salido muy temprano,\nque pasa por delante de la mar\nsintiéndose distinto a la mañana\nanterior, repitiendo sin embargo\ncada paso de ayer, como una máquina.\nSe ignora si es la bestia quien lo lleva,\no si en cambio conduce el ser humano;\no si se necesitan mutuamente\ncomo se necesitan con urgencia\nlos amantes los sábados.\nAmanece despacio y alguien grita\nsin que nadie pregunte ni responda.\n\nY es que sólo hay un hombre paseando,\nno arrastra tras de sí ningún dolor,\nno representa nada, no es un símbolo\nde ningún tipo, no es una metáfora\nde la pena y la angustia de vivir,\nhay poemas mejores para aquello.\n\nAquí sólo hay un hombre que ha sacado\na su perro a la calle unos minutos.\nQue pretende volver en cuanto pueda\na la cama a seguir imaginando\nque el perro se le muere, que de pronto\nse le destina a un sitio donde nadie\nentienda una palabra en castellano.\nUn sitio sin correas. Eso piensa\nel hombre que pasea con su perro,\nel hombre que ha salido tan temprano\nporque le aterroriza que otros hombres\npuedan interrogarle con preguntas\nsobre la raza y sobre las costumbres\ndel animal que tiene amordazado,\nmientras sale a la calle con su perro\naburrido del mundo, junto al mar,\ny piensa que ha vivido muchos años\ny que ha sido feliz muy pocas veces,\ny que ha tenido varios perros buenos\npero sólo un amor, y ese fue malo.\n\n(inédito)"},{"title":"La vela","year":"1984","text":"Y yo era del sol y el sol era bueno\n\ny yo era de las nubes y del mar\n\ny así estaba bien.\n\nY tú eras el acero y la montaña\n\ny el tiempo consumido y el futuro.\n\nY yo era de las muelas bucaneras\n\ny de los huesos rotos y del parche\n\ndel ojo vago y tú eras de las noches\n\ncuando se iba la luz; la vela amable\n\ny milagrosa tú, mi mundo mago."},{"title":"Llovía en todo el sigo XXI»","year":"1984","text":"«Llovía en todo el sigo XXI»\nleíste y sonreí porque te amaba.\n«Lo hubiera escrito hoy de otra manera»\nte dije y el Retiro era un incendio\nde palabras y vasos desechables\ny latas de refrescos en la sombra.\n«Hoy son libros de viejo y hace apenas\nUnos años que…» «¡No! –te interrumpí-.\nLo que importa es que pronto serán sólo materia»."},{"title":"Mi hijo, el poeta","year":"1984","text":"mi propio corazón una ciudad con un terrorista\n\natrincherado en el despacho del alcalde.\n\nStephen Dunn\n\nSi Padre llega tarde no es porque tenga miedo\n\nni porque arranque al fin la primavera\n\ny con ella los coches deshuesados\n\nque ponen rumbo al mar.\n\nSi Padre llega tarde\n\na la tercera planta, Sala 6,\n\ncardiología,\n\nserá por un despiste o porque quiere,\n\nporque, con todo, es dueño —todavía—\n\nde estas pequeñas cosas que no importan.\n\nY dicen nuestro nombre y me sonríe,\n\nvictorioso y anciano y en sus ojos\n\ndanza un pirata dueño de un secreto.\n\nLa doctora es más joven que el poeta\n\ny el pirata me apunta con la pata\n\nde palo y el secreto se posa en su hombro izquierdo:\n\nEste es mi hijo, barbulla y ya no quedan\n\nmesas libres en ninguna terraza y menudo día\n\npara ser otra cosa; millonario\n\ncon camisa pistacho; surfer; mendigo al sol\n\ncon los ojos cerrados, sonriendo.\n\nUn día para estar en otro sitio.\n\nUn día sin tener que hablar de nada.\n\nEste es mi hijo, el poeta.\n\nY el secreto aletea en la consulta\n\nrepitiendo la frase, poseído\n\npor la ira de las arenas insomnes y por el blanco\n\nimpoluto de la bata. Mi hijo, repite mi padre\n\ny el secreto regresa a su hombro izquierdo\n\ny nadie dice nada en la tercera\n\nplanta de la sala 6. Cardiología."},{"title":"Nací sin nada y llevo así","year":"1984","text":"Nací sin nada y llevo así, sin nada,\nunos ochenta y nueve años. Bastante\ncomo para poder desvariar\nsobre este banco junto a un Tetra Brick\nsin que nadie me escuche ni me crea.\nPero atended –o no; me da lo mismo–.Hay consenso en creer que tras la Guerra\n(que empezará en la costa de Israel)\ndominarán las ruinas las manadas\nde perros. Las mascotas\nadorables de un día crecerán\nhasta alcanzar tamaños nunca vistos\n(los perros más pequeños serán carne\no quizá incluso esclavos de otros perros).\nLa basura heredada\nserá de quien merezca poseerla\n(cucarachas y ratas siempre ha habido\ny siempre habrá: su mundo es el subsuelo);\nla lucha será entonces entre el Hombre\ny su fiero mejor amigo. «Es triste»\ndiríais si estuvierais escuchando\npero yo os diré ahora que es hermoso,\nque es un momento bello de la Historia.\nSólo entonces podrá el hombre medirse\ncon su idioma paupérrimo y ambiguo.\nSi los perros actúan como creo\nque harán (pues yo soy perro y perro viejo),\nesperarán el tiempo que haga falta:\ndiez años, veinte, treinta, cien ¿quién sabe?\nEl caso es que algún día los humanos\nse encontrarán terriblemente solos\nsin saber el motivo.\nVagarán\npor las ruinas de centros comerciales,\npor escuelas sin techo,\npor gimnasios roídos por el óxido,\npor piscinas vacías, discotecas\nenfangadas y plazas sin palomas.\nSe darán cuenta al fin del lodazal\nde ismos vacuos y eslóganes que hicieron\ny por el cual lucharon.\nY verán los espacios destruidos\nsintiendo una nostalgia más antigua\nque aquella pantomima de hormigón.\nUn arrepentimiento duro y áspero\nlos sobrecogerá\ny por primera vez no habrá poeta\ncapaz de traducir el sentimiento.\nPorque será imposible.\nY saldrán esa noche de las sombras\nlos perros como ángeles de dientes\ny en silencio.\nNo encontrarán ninguna resistencia.\nY empezará otra cosa para el mundo.\nY empezará otra cosa. Ya sin nombre."},{"title":"Pero si hablo de amor","year":"1984","text":"Pero si hablo de amor, si llegados a este punto hablo de amor,\nes porque todavía me permito cierto engaño;\nsobre la tierra fértil y cruel, cuerpo yermo de mercurio,\nprometo amar al hijo que no tengo\n(y que nunca podré tener)\ncon el mejor regalo de ese siglo:\npermanecer así, materia oscura."},{"title":"Rolls Royce","year":"1984","text":"Cuando cumplí los treinta me senté\n\na pensar en las cosas que quería.\n\nPensé en ti, en un futuro vago, en todo\n\nlo que duerme detrás de la escritura.\n\nY después, es verdad, pensé en un Rolls\n\nRoyce Phantom, o en cualquier Rolls Royce (¿importa?)\n\ny tuve la ilusión de tener uno\n\nantes de morir.\n\nY con otra cerveza dije bueno,\n\ncon ir en uno\n\nme doy por satisfecho. Me senté\n\ny me propuse ir en un Rolls Royce\n\ncomo objetivo único y legítimo.\n\nMás tarde recordé su funeral.\n\nEl Rolls que nos llevó hasta el crematorio.\n\nEl perfecto silencio del motor;\n\ncómo el coche aquel día no importaba."},{"title":"Ruedas","year":"1984","text":"Fuera ahora,\naléjate entre sombras, vete.\nDéjanos donde un día nos encontraste, solos.\n\nCosa.\nTropiezo.\nObjeto inhabitable. Puro amor.\n\nSolamente te pido que no regreses nunca."},{"title":"Self-service","year":"1984","text":"Self-service\nPara Sara\n\nYo nunca he pretendido nada más:\nestar vivo y consciente cuando mueras;\nporque yo no me fío,\nporque al final no hay nadie más que uno\nmismo y su tozudez y, claro está,\nsu amor.\n              Haz con tu vida lo que quieras,\nno te estoy proponiendo ningún pacto. \n\nLa gente es cada vez más y más joven\ny no es justo exigirle lo imposible.\n\nAsí que me reafirmo y me prometo\ny me cuido y procuro no morir\npara hacerte vivir un poco más, \n\nen mí."},{"title":"Ser inmigrante no es fácil","year":"1984","text":"Ser inmigrante no es fácil,\npero he comprendido pronto\nque si uno se hace pasar \npor italiano (aunque es algo \nmuy odioso para un griego)\nlos abusos se reducen \ncasi a la mitad respecto\na que te crean rumano.\nEs así. Cuento, además,\ncon la suerte de saber\nque vuestro italiano es más escaso\nincluso que el mío."},{"title":"The Quarter-Century Blues","year":"1984","text":"Hoy saldré a celebrar la dicha frágil\n de todos los productos congelados\n la imborrable fatiga del cartón\n y las cosas\n .\n las cosas porque tuve\n un profesor obeso de latín\n que siempre nos prohibió\n escribir las cosas\n por ser vagas las cosas pero nada\n decía este señor de mi deseo\n que fue siempre\n colmar los habitáculos de términos\n imprecisos\n hoy salgo a celebrar\n que hubo noches difusas donde todos\n podrían haber sido otra persona\n .\n pero, un momento, aquí\n quisiera detenerme\n bajar algo la voz y susurrar\n .\n ‘Sé que amaste a Miquel Martí i Pol\n mucho más que a Valente y no te culpo\n porque de vez en cuando yo también\n practico el bricolaje y hago footing’.\n .\n Una masa danzante en los pasillos,\n un problema, un brevísimo altercado\n seré, con todo, tuyo como nunca\n lo he sido hoy, hoy que tanto me conmueve,\n hoy que he cumplido veinticinco años."}],"topPainters":[{"dir":"okeeffe","name":"Georgia O’Keeffe","value":0.237621,"best":0.297251},{"dir":"sorolla","name":"Joaquín Sorolla","value":0.249286,"best":0.293572},{"dir":"amrita-sher-gil","name":"Amrita Sher-Gil","value":0.233309,"best":0.289645}],"topPairs":[{"pintor":"okeeffe","obra":"02_black_iris.jpg","poeta":"Clark, Ben","sim":0.4134,"p":4},{"pintor":"okeeffe","obra":"04_rams_head_white_hollyhock.jpg","poeta":"Clark, Ben","sim":0.380495,"p":14},{"pintor":"amrita-sher-gil","obra":"09_woman_on_charpai.jpg","poeta":"Clark, Ben","sim":0.367279,"p":3}]},{"name":"Eduardo de la Cruz","gender":"Hombre","period":"Poesía contemporánea, siglos XX-XXI","region":"España","profile":"https://segoedu.com/tareas/profile.png","poems":[{"title":"Noche en Alpha-7","year":"2024","text":"De noche, arropado\ny en pijama, cuando sueño,\nestamos subidos a una nave,\ncamino de Alpha-7,\ny por la ventanilla,\nallá en la historia cósmica,\nnos miro y descansamos.\nPor el espacio,\ncomo en un folio\nsin márgenes,\ny con nosotros,\npequeños asteroides,\nlos restos de una estrella\ny su jolgorio. ¿Quién guía\nnuestro viaje?\nEs el destino,\nel polvo de la luz\nque enciende nuestra casa\ny nos acoge. Desde antes\nde los soles y los mares,\nsuenan tus manos y las mías,\nel eco persistente de las flores\ny el amor.\nEs el destino,\nla huella del crepúsculo\nque abraza el cielo largo\ny nos da calma. Tus ojos\ny los míos,\nel murmullo que deja\nla risa en el silencio,\nel lienzo pintado por los dioses\natropelladamente.\nQue sí, es el destino,\nla estela de los astros\nque arropa nuestro lecho\ny nos envuelve. Un bosque\nde caricias y el tacto\namplificado de tu boca.\nLa destrucción de las galaxias\nque se arrastran\ncomo hojas secas en otoño.\nYa ves, con el destino,\nel polvo de lo eterno\nque forma nuestro espacio\ny nos acerca. Así es mi sueño,\ntodo eso en una noche,\ntodo eso en mi cabeza."},{"title":"Frente a la costas del tiempo…","year":"2024","text":"Frente a las costas del tiempo y de la escarcha, desnudo\nde silencio entre las manos y ansioso de latires,\nrespira un corazón de piel descalza. En las arterias,\nlos grumos de la noche y de las piedras, la plegaria\ndel ciclo de las olas. El reposo del sol bajo el olivo\nblanco. ¿Capaz que ya fue todo? ¿Acaso soy tan solo\nun peregrino sin camino bajo el amor y entre la luz\nde las estrellas?\nSereno de relojes y de alturas, pregunto a la vereda\n¿soy caminante? La tierra del sendero me responde,\n¿pero es que no lo ves? Lo tienes ahí delante. Los pájaros,\nlas flores, las montañas. Al fondo está la mar, ¡soy marinero!\nLa senda es transparente y está llena de barcos. La tormenta,\nlo salvaje y el abrazo escondido entre los acantilados.\n¿Acaso no lo has hecho ya otras veces? Capaz\nque no recuerdas el pasado. Aquí la casa, allí una fuente\ny el huerto de manzanos en la orilla, huele a menta. La belleza,\npintura y verso de todos los corales, me acompaña.\nEstoy a salvo."},{"title":"Satélites","year":"2023","text":"El día en que se queman las estrellas\nla luz blanca cae sobre unos hielos escondidos\nen la mesa y tres sillas plegables.\nLa bóveda oscura, despejada, el lago mínimo\ny los abrigos, abrimos tres cervezas, y una manta,\n¡acércate!\nEstoy en casa, en una casa de cuatro ruedas,\ncon piel de espuma y edredón. Soy un triángulo\nde amigos y en la montaña, unidos y enredados,\npor un cable de acero, cerca de dios,\nnos conocimos.\nUn fuego extraño cruza el cielo y una temprana primavera\nnos recuerda lo pequeño y el detalle,\nsomos amigos y es lo bello.\nTodo pasa y aún nos queda el entusiasmo\nde aquella noche en la que vimos\ncon asombro y a lo lejos\ncómo las estrellas se quemaron."},{"title":"Bambalinas","year":"2023","text":"Tu forma de mirar es el camino de la piel.\nLa cometa que vuela en el fuego viejo de la madrugada.\nDesliza en tu palabra el velo blanco de la irrealidad.\nEl brote de las alas en tu boca, un lienzo ríe.\nExtrañamiento.\nLas manzanas de tu rostro, el alimento, la pulpa de tu imagen.\nPaisaje, flor, simiente de un cántico narrado en abstracta primavera.\nDoscientas sinfonías y un latir de mariposas.\nLa mancha de una mora, la belleza derramada y el acento.\nEl giro arquitectónico de la naturaleza.\nEl último pedazo de tu voz es vertical y se deshace,\nallá entre los que están detrás del mundo.\nLa luz que me ilumina de todos los poemas.\nEl verso fiel, latente y consagrado, que anuncia con dulzura\nlas mieles de los astros y de la poesía."},{"title":"Poema cuántico","year":"2023","text":"Partículas tangentes,\ndesdobladas, en compresión atómica.\nVoluntades subterráneas, primigenias.\nEl caos se impacienta.\nAl otro lado, el abismo. La nada.\nAmor cosmológico latente.\nTodo está por crear. Tus pecas,\nlos arroyos, el color malva y un olivo.\nEl grito del universo afligido.\nMateria escondida, energía negra,\ngermen de constantes y proporciones.\nRealidades hechas de vacío.\nTu voz, en el origen.\nAbro mis ojos y apareces.\nTe pienso y estallo.\nBrota mi ser.\nAtardecer cuántico en mis pupilas.\nEstocástica radiante, incierta y caprichosa.\nEspectros luminosos de partículas.\nPredicción ondulatoria.\nDetrás de todo, ¿quién?\nA dónde va la luz cuando se aleja.\nA dónde el tacto de tu piel cuando me deja.\nEl alma vertical entrelazada.\nEstructura disipada tejida con hilos celestiales,\neternidad latente y en las esquinas, amor.\nPartícula existencial, mecánica absoluta.\nRetorno a los altares del origen.\nSin palabras,\nno hay Dios. Entre los versos, tú.\nLa lírica hecha carne, la física desvanecida.\nPor los bordes, rebosante, se derrama la belleza.\nYa no hay otra forma de entender el universo."},{"title":"¡No era una caja!","year":"2023","text":"Ya solo espero que la noche me trague.\nBajo mis pies se abra la tierra y desaparecer.\nHeme aquí entre los hombres y las mujeres,\npuesta por el divertimento de los dioses.\nJuego de los unos, esclava de las otras.\nPandora, ven aquí,\nPandora, guarda esto.\nPandora, trae aquello.\nNi una sola caricia en las palabras.\nGuardo, traigo y voy\ncargada de ánforas, de rabia\ny de curiosidad.\nEn tanto que\nuna se me cae y se hace añicos.\nCómo iba yo a saber si de aceite,\nde miel o de manzanas,\ny no de aquellas molestias vertidas.\nReúno con la escoba los despojos.\nSé lo qué dirán de mí, por la calle.\nPandora, torpe.\nPandora, fisgona.\nPandora, inoportuna.\nLas manchas, las del suelo y en mi nombre,\nno se borran. Y no dejo de pensar\npor qué nadie me advirtió.\nPandora, ¡ten cuidado!"},{"title":"Tinieblas","year":"2023","text":"A oscuras, de madrugada, tus besos\nocultos en la penumbra,\nsecretos, bajo una noche\nde estrellas, olivos y serranía.\nSe abre una puerta, los cuerpos\nse buscan, las bocas se encuentran,\nes el hambre quien se come y se devora\ncon un ansia clandestina.\nOjos aglomerados observan\nnos miran, sin ver,\nsin saber, nos vigilan, nosotros\nseguimos jugando a ser fresas\nde campo, sabrosas,\nel rojo en tu cuello, mi mano\nen las flores, hermosas,\nlas bocas se muerden, inquietas,\nel tiempo y los latires\nse detienen,\nlas ganas y la sangre\nse aceleran.\nPronto la luz y separados,\nvolvemos a fundirnos con la casa.\nTus besos por furtivos, verdaderos,\nel juego por discreto, terminado.\nNos dormimos.\nPronto el sol y tu pijama,\ntu pelo alborotado y somnolientos\nbuscamos el reencuentro en la cocina\ny el aroma del café de la mañana\nrecién hecho."},{"title":"Continentes","year":"2022","text":"Imagina que tú y que yo\nmuy tarde ya en la noche\nnos chocamos\nfrente a frente,\nbaile a baile,\nboca a boca.\nImagínatelo.\nuna noche de alcohol y sótano\nen blanco, tú, en negro, yo\nun verano y un invierno\ncontinentes oceánicos\ncontinentes que se rozan\nnos situamos a medio verso,\nnos encontramos en la piel,\nen la frontera que es la piel\nnos comemos, embriagados\nde poesía,\nde pornografía,\nbiografías que se cruzan\nen un punto\nuna noche\ny al caer el día\ny el sol\nsobre las macetas secas\nel abismo entre las sábanas\nel cuerpo negado\nla cama alborotada\nla ropa por los suelos\nel hechizo ya deshecho\ntazones de remordimiento\ncucharadas que saben a distancia\nmiradas suspicaces\ndeschocamos\ncontinentes que se alejan\ndos continentes extraños."},{"title":"Viajar","year":"2022","text":"Viajar,\neste placer de alejarse\nlejos, nunca es suficiente.\nViajar,\nhacer la maleta, marcharse.\nEl viaje empieza en la mente y después\nde imaginar un destino,\nse dibuja sobre un mapa\ny se termina con los pies.\nViajar y sentir que se viaja\na mil y un sitios diferentes.\nPartir sin saber a dónde,\nsobrevolar las ciudades,\nrecorrer los continentes,\nnavegar sobre los mares.\nEncontrar lo que se esconde, lo invisible,\ny amanecer cada mañana\npensando que todo es posible.\nViajo, viajaré, viajaba,\npalabras que son curiosas,\nemociones conjugadas.\nViajar, viajero, viajante,\ndeclinaciones hermosas\npalabras enamoradas.\nEl verbo viajar es mi amante\nnerviosa que siempre me espera.\nEsperas en estaciones,\npuertos y terminales.\nReencuentros y despedidas.\nEsperas acompañadas\nde libros y auriculares.\nLlantos, abrazos\ny besos de bienvenida.\nSentado en el tren, prefiero\nmirar por la ventanilla,\ncon mis ojos de viajero,\nluz, paisaje y geografía.\nObservar por la ventana\ndel avión que sube, el nacer\nde la mañana y el sol que estalla\ntras una nube.\nD.F., Atenas, Lisboa\nlos glaciares del montblanc\ny el desierto de Marruecos.\nEgipto, Islandia y Nepal.\nViajar cada vez más lejos,\nY en mi cápsula espacial\nsurcar los siete universos,\ny al llegar al más allá\ndel infinito —¡qué placer!—\natrapar con mi mano\nel bigbang, sacudirlo\ny ponerlo del revés.\nDescender hacia las profundidades\ny observar las chimeneas\ndonde nacen las bacterias\nen los fondos abismales.\nViajar no es hacer turismo.\nComenzamos el trayecto\ny no sabemos quién somos.\nPor extraños mecanismos\nen nosotros algo pasa,\nnos hace cambiar por dentro\ny regresamos a casa\nsin volver a ser los mismos.\nComenzamos a viajar\ny no sabemos quién somos.\nPor extraños mecanismos\nen nosotros algo pasa,\npor dentro, nos hace cambiar\ny regresamos a casa\nsin volver a ser los mismos."},{"title":"Fotografía","year":"2022","text":"Estamos del revés\nnuestras manos son de arena\nde salitre, nuestra piel\na lo lejos una bola\nde helado de naranja\nse derrite.\nParece tan sencillo\ncaminar sobre la mar\ny tocar el horizonte\ncon la yema de mis dedos\nla línea que separa\nde lo terrenal,\nlo celeste azul, lo celeste cielo\nlínea que al tocarla vibra\nigual que tú, aquel día\ncomo la cuerda de un violín\norgásmica sinfonía.\nCuerpos que se elevan\ntardes que descienden\nalmas que se besan.\nPrueba una vez\ny otra\ny otra\ny otra vez\nel momento que se viene\nromántica litografía\nla respiración se aguanta\nel músculo se tensa\ny el tiempo se detiene.\nFotografía.\nSi esta vez sí, esta vez siempre.\nVerano prolongado, verano inagotable\nguardado en los adentros\nverano interminable, verano permanente\nun quiero cerca eterno.\nSi esta vez sí, ¿entonces siempre?\nPromesas convertidas en poemas\npromesas derretidas como alas\ny una pregunta suena,\nen mi cabeza, recurrente,\nsin respuesta, ¿de verdad es tan difícil\ncaminar sobre las aguas?"},{"title":"Quizá regrese esta noche","year":"2022","text":"Quizá regrese esta noche.\nEsta noche sí, quizá.\nY remita esta lluvia interminable,\nque ya no sé si es lluvia o llanto,\neste caer eterno de agua y melancolía,\nel cielo deshaciéndose sobre este manto\nde hojas amarillas, ramas rotas y caminos vacíos.\nY los vientos dejen de silbar\ny dejen de traer y de llevar\ny dejen de buscar\nentre los árboles desnudos y sequen,\npor fin,\nla humedad de la corteza,\nla humedad de mis huesos.\nEsta noche quizá regrese.\nY los grillos harán fiesta,\ny el ulular de los búhos será una sinfonía,\ny las hojas del suelo se pintarán de verde\ny volverán a los árboles,\ny la lluvia se sentirá piel y sabor dulce,\ny la noche sonará a luz y será sol,\ny el camino se llenará de ti.\nQuizá esta noche regreses.\nEsta noche quizá, sí."},{"title":"Costumbres","year":"2022","text":"Por la noche, yo acostumbro\ncuando duermo a dejar la\nluz de mi cuarto encendida,\nla cortina sin echar, entreabierta,\ny ver la luz de la farola reflejada en la ventana.\nAcostumbro a no cerrar la puerta.\nEn el pasillo, siempre pongo unas migajas,\nun camino, como un rastro,\ny sobre un plato, los gajos de unas naranjas\nque compré por la mañana en el mercado.\nUn vaso de agua fresca en la mesilla,\njunto al móvil encendido,\ncon el volumen bien alto,\npor si llamas y estoy dormido.\nTu pijama limpio y doblado bajo la almohada\ncon olor a flor y a suavizante\ny en tu lado de la cama,\nun espacio y su vacío,\namante que me acompaña\ndesde el día en que te fuiste\ny me dejaste aquí, conmigo\ny mis asuntos.\nYa ves, así son las costumbres\nsin tu calor en mis sábanas.\nLo hago cada noche, y luego, en las mañanas\nme miro en el espejo y me pregunto\nsi la luz nunca apagada,\nsi la persiana subida,\nsi los gajos cortados,\nsi las migajas echadas,\nsi el agua fresca vertida,\nsi tu pijama doblado,\nsi estos versos que ahora escribo,\n¿habrán servido de algo?\nY cuando quieras volver\nque te muestren el camino.\nY encuentres, al regresar,\nque no cambié nada de sitio\ny todo sigue en su lugar."},{"title":"Verbos intransitivos","year":"2022","text":"Siempre intento amar de manera intransitiva.\nEscribir una oración sin complemento\ncon sujeto, verbo y predicado,\nconstruida en voz activa.\nAmar como vocación, verbo cierto,\ncuya acción no se proyecta\nsobre un objeto directo.\nAmar desde dentro y hacia fuera\ncomo quien mira un paisaje al llegar la primavera.\nAmar desde fuera y hacia dentro,\ncomo un suspiro, una sorpresa\nque nos deja sin aliento\ny nos llena el alma de colores.\nAmar, sí, amar.\nAmar en mil direcciones.\nAmar y volver a amar.\nAmar, una y otra vez,\n—de manera intransitiva—\ncomo el verbo respirar, con el permiso\nde una brizna de aire puro.\nPartir sin previo aviso.\nIluminar una estancia\ndonde antes todo era oscuro\ny difuminar los límites entre nosotros y el mundo.\nChocar como una ola que, al morir,\nno se esconde, sino que vuelve a ser mar y océano y cántaros\nde lluvia.\nPartir sin saber a dónde.\nAnidar como los pájaros,\nen las ramas de algún árbol\ny, al crecer, volar un cielo limpio o navegar una tormenta,\npero nunca más\nvolver.\nMentir y hacerlo con piedad como sin darse ni cuenta\nsin maltratar la verdad.\nLlorar lágrimas\nde tristeza un día,\nagua salada que me recorre la cara;\npero al pasar de las páginas\nla historia manchada de pena,\nse convierte en alegría.\nBailar swing toda la noche hasta tener agujetas,\nempapados de sudor, y después ya en tu cama, en tu regazo\ninflamarnos con amor\ny, al terminar, mirar la luna y las estrellas\na través de la ventana, rodearte con mi brazo, dormirnos, soñar con ellas, acariciarte y, sin prisas, esperar a la mañana.\nBromear y despertarnos con un beso,\nentre arrumacos y risas.\nPodría seguir así —como ejemplo—\nusando un verbo tras otro,\nverbos que no tienen complemento\no tienen el complemento roto.\nVerbos que atraviesan el objeto y lo superan.\nAsí entiendo yo el verbo amar,\nun amar sublime, despacio y lento,\nuna acción que se proyecta al infinito, sin medida,\ny al llegar en un momento a los confines y expandirse,\nrellena todo el espacio de vida.\nUn amar intransitivo que amar —quiera o no quiera— siempre comienza y amar siempre termina contigo."},{"title":"Orillas de luz y geometría","year":"2021","text":"Noche de atención     excedida y agitada.\nFin de la novela,\núltimos naufragios de mar confesional,\ndecorado e interior.\nNovela lírica,\nentrañas de un escritor,\ncincel dorado y puntillista.\nTiempo intermitente,\nfrecuencia invernal,\ngeometría ennochecida,\norilla oscura\ndel día que termina,\nzozobra de un alma\nsugerida y sugerente.\nPáginas concéntricas cerrándose\nsobre sí mismas,\ndescanso merecido y diletante,\nespera de figuras,\nguindas y requiebros de lenguaje.\nSintaxis adornada de memoria,\narquitectura tipográfica.\nSemántica mimada\nde caprichos y colores.\nCostas alcanzadas de arena,\naroma nubeloso de algodón.\nMetamorfosis de éter,\nojos aguilados.\nBosques horizontales de lexemas,\ncaricias cantadas.\nHojas de literatura perenne,\nrectangular y profética.\nPalabras salientes,\nuntadas y engendradas,\nguardadas en memoria\nde buhardilla,\nvertical y descendida."},{"title":"Haiku I","year":"2026","text":"tierra de nómadas\ndesentierro las raíces\nlas semillas brotan"},{"title":"Haiku II","year":"2026","text":"caminante de orillas\nfugitivo de los inviernos\nel horizonte me grita"}],"topPainters":[{"dir":"okeeffe","name":"Georgia O’Keeffe","value":0.273831,"best":0.333505},{"dir":"kusama","name":"Yayoi Kusama","value":0.237276,"best":0.315149},{"dir":"sorolla","name":"Joaquín Sorolla","value":0.261431,"best":0.302923}],"topPairs":[{"pintor":"okeeffe","obra":"02_black_iris.jpg","poeta":"Eduardo de la Cruz","sim":0.415318,"p":3},{"pintor":"okeeffe","obra":"06_sky_above_clouds.jpg","poeta":"Eduardo de la Cruz","sim":0.410244,"p":9},{"pintor":"okeeffe","obra":"07_pelvis_with_the_distance.jpg","poeta":"Eduardo de la Cruz","sim":0.40115,"p":9}]},{"name":"Emily Dickinson","gender":"Mujer","period":"Poesía lírica, siglo XIX","region":"Estados Unidos","profile":"https://poets.org/sites/default/files/images/biographies/155_EmilyDickinsonSmall.jpg","poems":[{"title":"Hope is the thing with feathers","year":"1861","text":"\"Hope\" is the thing with feathers —\nThat perches in the soul —\nAnd sings the tune without the words —\nAnd never stops — at all —\n\nAnd sweetest — in the Gale — is heard —\nAnd sore must be the storm —\nThat could abash the little Bird\nThat kept so many warm —\n\nI've heard it in the chillest land —\nAnd on the strangest Sea —\nYet — never — in Extremity,\nIt asked a crumb — of me."},{"title":"I felt a Funeral, in my Brain","year":"1861","text":"I felt a Funeral, in my Brain,\nAnd Mourners to and fro\nKept treading — treading — till it seemed\nThat Sense was breaking through —\n\nAnd when they all were seated,\nA Service, like a Drum —\nKept beating — beating — till I thought\nMy Mind was going numb —\n\nAnd then — a Plank in Reason, broke,\nAnd I dropped down, and down —\nAnd hit a World, at every plunge,\nAnd Finished knowing — then —"},{"title":"Because I could not stop for Death","year":"1863","text":"Because I could not stop for Death —\nHe kindly stopped for me —\nThe Carriage held but just Ourselves —\nAnd Immortality.\n\nWe slowly drove — He knew no haste\nAnd I had put away\nMy labor and my leisure too,\nFor His Civility —\n\nWe passed the School, where Children strove\nAt Recess — in the Ring —\nWe passed the Fields of Gazing Grain —\nWe passed the Setting Sun —\n\nOr rather — He passed Us —\nThe Dews drew quivering and Chill —\nFor only Gossamer, my Gown —\nMy Tippet — only Tulle —\n\nWe paused before a House that seemed\nA Swelling of the Ground —\nThe Roof was scarcely visible —\nThe Cornice — in the Ground —\n\nSince then — 'tis Centuries — and yet\nFeels shorter than the Day\nI first surmised the Horses' Heads\nWere toward Eternity —"},{"title":"I'm Nobody! Who are you?","year":"1861","text":"I'm Nobody! Who are you?\nAre you — Nobody — too?\nThen there's a pair of us!\nDon't tell! they'd advertise — you know!\n\nHow dreary — to be — Somebody!\nHow public — like a Frog —\nTo tell one's name — the livelong June —\nTo an admiring Bog!"},{"title":"My Life had stood — a Loaded Gun","year":"1863","text":"My Life had stood — a Loaded Gun —\nIn Corners — till a Day\nThe Owner passed — identified —\nAnd carried Me away —\n\nAnd now We roam in Sovreign Woods —\nAnd now We hunt the Doe —\nAnd every time I speak for Him\nThe Mountains straight reply —\n\nAnd do I smile, such cordial light\nUpon the Valley glow —\nIt is as a Vesuvian face\nHad let its pleasure through —\n\nAnd when at Night — Our good Day done —\nAnd I in His Chamber — place —\nPile the Balls of Aural Light —\nThen — brooding in the Base —\n\nAnd I — and He — superior —\nCircumference without a Crack —"},{"title":"I heard a Fly buzz — when I died","year":"1862","text":"I heard a Fly buzz — when I died —\nThe Stillness in the Room\nWas like the Stillness in the Air —\nBetween the Heaves of Storm —\n\nThe Eyes around — had wrung them dry —\nAnd Breaths were gathering firm\nFor that last Onset — when the King\nBe witnessed — in the Room —\n\nI willed my Keepsakes — Signed away\nWhat portion of me be\nAssignable — and then it was\nThere interposed a Fly —\n\nWith Blue — uncertain stumbling Buzz —\nBetween the light — and me —\nAnd then the Windows failed — and then\nI could not see to see —"},{"title":"Tell all the truth, but tell it slant","year":"1868","text":"Tell all the truth but tell it slant —\nSuccess in Circuit lies\nToo bright for our infirm Delight\nThe Truth's superb surprise\n\nAs Lightning to the Children eased\nWith explanation kind\nThe Truth must dazzle gradually\nOr every man be blind —"},{"title":"Wild Nights — Wild Nights!","year":"1861","text":"Wild Nights — Wild Nights!\nWere I with thee\nWild Nights should be\nOur luxury!\n\nFutile — the winds —\nTo a Heart in port —\nDone with the Compass —\nDone with the Chart!\n\nRowing in Eden —\nAh — the Sea —\nMight I but moor — to Night —\nIn Thee!"},{"title":"I dwell in Possibility","year":"1862","text":"I dwell in Possibility —\nA fairer House than Prose —\nMore numerous of Windows —\nSuperior — for Doors —\n\nOf Chambers as the Cedars —\nImpregnable of eye —\nAnd for an everlasting Roof\nThe Gambrels of the Sky —\n\nOf Visitors — the fairest —\nFor Occupation — This —\nThe spreading wide my narrow Hands\nTo gather Paradise —"},{"title":"Success is counted sweetest","year":"1859","text":"Success is counted sweetest\nBy those who ne'er succeed.\nTo comprehend a nectar\nRequires sorest need.\n\nNot one of all the purple Host\nWho took the Flag to day\nCan tell the definition\nSo clear of victory\n\nAs he defeated — dying —\nOn whose forbidden ear\nThe distant strains of triumph\nBurst agonized and clear!"},{"title":"If I can stop one Heart from breaking","year":"1862","text":"If I can stop one heart from breaking,\nI shall not live in vain;\nIf I can ease one life the aching,\nOr cool one pain,\n\nOr help one fainting robin\nUnto his nest again,\nI shall not live in vain."},{"title":"A Bird came down the Walk","year":"1862","text":"A Bird came down the Walk —\nHe did not know I saw —\nHe bit an Angle Worm in halves\nAnd ate the fellow, raw,\n\nAnd then, he drank a Dew\nFrom a convenient Grass —\nAnd then hopped sidewise to the Wall\nTo let a Beetle pass —\n\nHe glanced with rapid eyes,\nThat hurried all around —\nThey looked like frightened Beads, I thought —\nHe stirred his Velvet Head\n\nLike one in danger, Cautious,\nI offered him a Crumb\nAnd he unrolled his feathers\nAnd rowed him softer home —\n\nThan Oars divide the Ocean,\nToo silver for a seam —\nOr Butterflies, off Banks of Noon\nLeap, plashless as they swim."},{"title":"To fight aloud is very brave","year":"1862","text":"To fight aloud, is very brave —\nBut gallanter, I know\nWho charge within the bosom,\nThe Cavalry of Woe —\n\nWho win, and nations do not see —\nWho fall — and none observe —\nWhose dying eyes, no Country\nRegards with patriot love —\n\nWe trust, in plumed procession\nFor such, the Angels go —\nRank after Rank, with even feet\nAnd Uniforms of Snow."},{"title":"My life closed twice before its close","year":"1862","text":"My life closed twice before its close —\nIt yet remains to see\nIf Immortality unveil\nA third event to me\n\nSo huge, so hopeless to conceive\nAs these that twice befell.\nParting is all we know of heaven,\nAnd all we need of hell."},{"title":"Dear March — Come in —","year":"1871","text":"Dear March — Come in —\nHow glad I am —\nI hoped for you before —\nPut down your Hat —\nYou must have walked —\nHow out of Breath you are —\n\nDear March, how are you, and the Rest —\nDid you leave Nature well —\nOh March, Come right upstairs with me —\nI have so much to tell —\n\nI got your Letter, and the Birds —\nThe Maples never knew That you were coming — I declare,\nHow red their Faces grew —\n\nBut, March, forgive me —\nAnd all those Hills you left for me to see —\nI have not got a Peach from any\nSince yours was true —\n\nDear March, come right upstairs with me —\nI have so much to tell —\nI got your Letter, and the Birds —\nThe Maples never knew —\n\nYou were just as fair as people\nI had seen before —\nAnd I went on, to tell you all —\nAbout the Door —\n\nI must declare, how red their Faces grew —\nBut, March, forgive me —\nAnd all those Hills you left for me to see —\nI have not got a Peach from any\nSince you went away —"},{"title":"I taste a liquor never brewed","year":"1861","text":"I taste a liquor never brewed —\nFrom Tankards scooped in Pearl —\nNot all the Frankfort Berries\nYield such an Alcohol!\n\nInebriate of air — am I —\nAnd Debauchee of Dew —\nReeling — thro' endless summer days —\nFrom inns of molten Blue —\n\nWhen \"Landlords\" turn the drunken Bee\nOut of the Foxglove's door —\nWhen Butterflies — renounce their \"drams\" —\nI shall but drink the more!\n\nTill Seraphs swing their snowy Hats —\nAnd Saints — to windows run —\nTo see the little Tippler\nLeaning against the — Sun!"},{"title":"There's a certain Slant of light","year":"1861","text":"There's a certain Slant of light,\nWinter Afternoons —\nThat oppresses, like the Heft\nOf Cathedral Tunes —\n\nHeavenly Hurt, it gives us —\nWe can find no scar,\nBut internal difference\nWhere the Meanings, are —\n\nNone may teach it — Any —\n'Tis the seal Despair —\nAn imperial affliction\nSent us of the Air —\n\nWhen it comes, the Landscape listens —\nShadows — hold their breath —\nWhen it goes, 'tis like the Distance\nOn the look of Death —"},{"title":"I died for Beauty — but was scarce","year":"1862","text":"I died for Beauty — but was scarce\nAdjusted in the Tomb\nWhen One who died for Truth, was lain\nIn an adjoining Room —\n\nHe questioned softly \"Why I failed\"?\n\"For Beauty\", I replied —\n\"And I — for Truth — Themself are One —\nWe Brethren, are\", He said —\n\nAnd so, as Kinsmen, met a Night —\nWe talked between the Rooms —\nUntil the Moss had reached our lips —\nAnd covered up — Our Names —"},{"title":"After great pain, a formal feeling comes","year":"1862","text":"After great pain, a formal feeling comes —\nThe Nerves sit ceremonious, like Tombs —\nThe stiff Heart questions — was it He, that bore,\nAnd Yesterday — or Centuries before?\n\nThe Feet, mechanical, go round —\nOf Wooden way — of Ground —\nOr Air, or Ought — regardless grown,\nA Quartz contentment, like a stone —\n\nThis is the Hour of Lead —\nRemembered, if outlived,\nAs Freezing persons, recollect the Snow —\nFirst — Chill — then Stupor — then the letting go —"},{"title":"This is my letter to the World","year":"1862","text":"This is my letter to the World\nThat never wrote to Me —\nThe simple News that Nature told —\nWith tender Majesty\n\nHer Message is committed\nTo Hands I cannot see —\nFor love of Her — Sweet — countrymen —\nJudge tenderly — of Me"}],"topPainters":[{"dir":"okeeffe","name":"Georgia O’Keeffe","value":0.246415,"best":0.300151},{"dir":"kusama","name":"Yayoi Kusama","value":0.21283,"best":0.278007},{"dir":"monet","name":"Claude Monet","value":0.216548,"best":0.275959}],"topPairs":[{"pintor":"okeeffe","obra":"02_black_iris.jpg","poeta":"Emily Dickinson","sim":0.365756,"p":16},{"pintor":"okeeffe","obra":"05_from_the_lake.jpg","poeta":"Emily Dickinson","sim":0.362951,"p":16},{"pintor":"okeeffe","obra":"06_sky_above_clouds.jpg","poeta":"Emily Dickinson","sim":0.351089,"p":16}]},{"name":"Ibarbourou, Juana de","gender":"Mujer","period":"Modernismo, siglo XX","region":"Uruguay","profile":"https://images2.conchology.be/biography/medium/21360/photo-1.jpg","poems":[{"title":"Agosto","year":"1895-1979","text":"Agosto agrio y ceñudo, \nde albas heladas y lentas, \nde amor dormido o ausente\ny de quemadas violetas;\n\nAgosto, neblina y sombra.\nAgosto, esperanza muerta.\n\nSiento en el alma tu espada,\n¡tu puñal de helado acero!\nMe pesa como la piedra\naquel ensueño de Enero.\n\n¡Ya he perdido mi abejar,\nmi anillo de oro y mi velo! \n\n¡Ya no iré, paso menudo,\nsonrisa pronta, faz clara,\na mirarme en el espejo\nfidelísimo del agua!\n\n¡Ay, juventud que se va\ncuando me era más cara!"},{"title":"Amor","year":"1895-1979","text":"El amor es fragante como un ramo de rosas.\nAmando, se poseen todas las primaveras.\nEros trae en su aljaba las flores olorosas\nde todas las umbrías y todas las praderas.\n\nCuando viene a mi lecho trae aroma de esteros,\nde salvajes corolas y tréboles jugosos.\n¡Efluvios ardorosos de nidos de jilgueros,\nocultos en los gajos de los ceibos frondosos!\n\n¡Toda mi joven carne se impregna de esa esencia!\nPerfume de floridas y agrestes primaveras\nqueda en mi piel morena de ardiente transparencia\n\nperfumes de retamas, de lirios y glicinas.\nAmor llega a mi lecho cruzando largas eras\ny unge mi piel de frescas esencias campesinas."},{"title":"Amémonos","year":"1895-1979","text":"Bajo las alas rosa de este laurel florido,\namémonos. El viejo y eterno lampadario\nde la luna ha encendido su fulgor milenario\ny este rincón de hierba tiene calor de nido.\n\nAmémonos. Acaso haya un fauno escondido\njunto al tronco del dulce laurel hospitalario\ny llore al encontrarse sin amor, solitario,\nmirando nuestro idilio frente al prado dormido.\n\nAmémonos. La noche clara, aromosa y mística\ntiene no sé qué suave dulzura cabalística.\nSomos grandes y solos sobre el haz de los campos\n\ny se aman las luciérnagas entre nuestros cabellos,\ncon estremecimientos breves como destellos\nde vagas esmeraldas y extraños crisolampos."},{"title":"Angustia","year":"1895-1979","text":"Hoy estoy triste, amor.Hoy tengo el alma\nGris y desmelenada.\n¡Tierra propicia para toda pena!\n¡Para todo placer tierra negada!\nLa rosa de mi cuerpo\nHoy es lirio beato.\nCon triples vendas la ciñó la angustia\nY yo con triples velos la recato.\nHoy estoy triste, amor. Hoy no pretendo\nSentir mi risa.\n¡Me endurece los labios\nun agror de ceniza!"},{"title":"Así es la rosa","year":"1895-1979","text":"De la matriz del día\nse alzó la rosa vertical y blanca\nmientras todo rugía:\nla tierra, el aire, el agua.\n\nTendí la mano para protegerla,\ncriatura de paz y de armonía,\ncompleta, virgen, intocable, exacta\nen la extensión total del mediodía.\n\nY me llevó el brazo la metralla.\nImpávida seguía\nen su serenidad y su victoria,\naunque en mi sangre la embebía.\n\nNi mi alarido hizo temblar sus pétalos\nni apagó su fragancia mi agonía.\nEra la rosa, la perfecta y única.\nNada la detenía."},{"title":"Bajo la lluvia","year":"1895-1979","text":"¡Cómo resbala el agua  por mi espalda!\n¡Cómo moja mi falda, \ny pone  en mis mejillas su frescura de nieve!\nLlueve, llueve, llueve,\ny voy,  senda adelante,\ncon el alma ligera y la cara radiante,\nsin sentir, sin soñar,\nllena de la voluptuosidad de no pensar.\n\nUn pájaro se baña\nen una charca turbia. Mi presencia le extraña,\nse detiene… me mira… nos sentimos amigos…\n¡Los dos amamos muchos cielos, campos y trigos!\nDespués es el asombro\nde un labriego que pasa con su azada al hombro\ny la lluvia me cubre de todas las fragancias \nde los setos de octubre.\nY es, sobre mi cuerpo por el agua empapado\ncomo un maravilloso y estupendo tocado\nde gotas cristalinas, de flores deshojadas\nque vuelcan a mi paso las plantas asombradas.\nY siento, en la vacuidad\ndel cerebro sin sueño, la voluptuosidad\ndel placer infinito, dulce y desconocido,\nde un minuto de olvido.\nLlueve, llueve, llueve,\ny tengo en alma y carne, como un frescor de nieve."},{"title":"Como la primavera","year":"1895-1979","text":"Como una ala negra tendí mis cabellos\nsobre tus rodillas.\nCerrando los ojos su olor aspiraste,\ndicendome luego:\n-¿Duermes sobre piedras cubiertas de musgos?\n¿Con ramas de sauces te atas las trenzas?\n¿ Tu almohada es de trébol? ¿Las tienes tan negras\nporque acaso en ella exprimiste un zumo\nretinto y espeso de moras silvestres?\n¡Qué fresca y extraña fragancia te envuelve!\nHueles a arroyuelos, a tierra y a selvas.\n¿Que perfume usas? Y riendo te dije:\n-¡Nintuno, ninguno!\nTe amo y soy joven, huelo a primavera.\nEste olor que sientes es de carne firme,\nde mejillas claras y de sangre nueva.\n¡Te quiero y soy joven, por eso es que tengo\nlas mismas fragancias de la primavera!"},{"title":"Como una sola flor desesperada","year":"1895-1979","text":"Lo quiero con la sangre, con el hueso,\ncon el ojo que mira y el aliento,\ncon la frente que inclina el pensamiento,\ncon este corazón caliente y preso,\n\ny con el sueño fatalmente obseso\nde este amor que me copa el sentimiento,\ndesde la breve risa hasta el lamento,\ndesde la herida bruja hasta su beso. \n\nMi vida es de tu vida tributaria,\nya te parezca tumulto, o solitaria,\ncomo una sola flor desesperada. \n\nDepende de él como del leño duro\nla orquídea, o cual la hiedra sobre el muro,\nque solo en él respira levantada."},{"title":"Cual la mujer de lot","year":"1895-1979","text":"Un perfume de amor me acompañaba.\nVolvía hacia la aldea de la cita,\nbajo la paz suprema e infinita\nque el ocaso en el campo destilaba.\n\nEn mis labios ardientes aleteaba\nla caricia final, pura y bendita,\ny era como una alegre Sulamita\nque a su lar, entre trigos regresaba.\n\nY al llegar a un recodo del camino\ntras el cual queda oculto ya el molino,\nel puente y la represa bullidora,\n\nvolví atrás la cabeza un breve instante,\ny bajo el tilo en flor, ¡vi a mi amante\nque besaba en la sien a una pastora!"},{"title":"Descanso","year":"1895-1979","text":"Delicia, delicia de la casa en sombra,\nDe la casa fresca bajo la canícula,\nDe la mecedora y el libro en la verde\nPenumbra del patio techado de parras\nDonde runrunean avispas glotonas\nY toda la siesta canta una chicharra.\nY luego, ¡delicia del sueño que afloja\nLa loca y eterna tensión de mis nervios!"},{"title":"Despecho","year":"1895-1979","text":"¡Ah, qué estoy cansada! Me he reido tanto,\ntanto, que a mis ojos ha asomado el llanto;\ntanto, que este rictus que contrae mi boca\nes un rastro extraño de mi risa loca.\n\nTanto, que esta intensa palidez que tengo\n(como en los retratos de viejo abolengo)\nes por la fatiga de la loca risa\nque en todo mi cuerpo su sopor desliza.\n\n¡Ah, qué estoy cansada! Déjame que duerma;\npues, como la angustia, la alegría enferma.\n¡Qué rara ocurrencia decir que estoy triste!\n¿Cuándo más alegre que ahora me viste?\n\n¡Mentira! No tengo ni dudas, ni celos,\nNi inquietud, ni angustias, ni penas, ni anhelos,\nSi brilla en mis ojos la humedad del llanto,\nes por el esfuerzo de reirme tanto…"},{"title":"El dulce milagro","year":"1895-1979","text":"¿Que es esto? ¡Prodigio! Mis manos florecen.\nRosas, rosas, rosas a mis dedos crecen.\nMi amante besóme las manos, y en ellas,\n¡oh gracia! brotaron rosas como estrellas.\n\nY voy por la senda voceando el encanto\ny de dicha alterno sonrisa con llanto\ny bajo el milagro de mi encantamiento\nse aroman de rosas las alas del viento.\n\nY murmura al verme la gente que pasa:\n\"¿No veis que está loca? Tornadla a su casa.\n¡Dice que en las manos le han nacido rosas\ny las va agitando como mariposas!\"\n\n¡Ah, pobre la gente que nunca comprende\nun milagro de éstos y que sólo entiende\nQue no nacen rosas más que en los rosales\ny que no hay más trigo que el de los trigales!\n\nQue requiere líneas y color y forma,\ny que sólo admite realidad por norma.\nQue cuando uno dice: \"Voy con la dulzura\",\nde inmediato buscan a la criatura.\n\nQue me digan loca, que en celda me encierren\nque con siete llaves la puerta me cierren,\nque junto a la puerta pongan un lebrel,\ncarcelero rudo carcelero fiel.\n\nCantaré lo mismo: \"Mis manos florecen.\nRosas, rosas, rosas a mis dedos crecen\".\n¡Y toda mi celda tendrá la fragancia \nde un inmenso ramo de rosas de Francia!"},{"title":"El fuerte lazo","year":"1895-1979","text":"Crecí\npara ti.\nTálame. Mi acacia\nimplora a tus manos su golpe de gracia.\n\nFlorí \npara ti.\nCórtame. Mi lirio\nal nacer dudaba ser flor o ser cirio.\n\nFluí\npara ti.\nBébeme. El cristal\nenvidia lo claro de mi manantial.\n\nAlas di\npor ti.\nCázame. Falena,\nrodeé tu llama de impaciencia llena.\n\nPor ti sufriré.\n¡Bendito sea el daño que tu amor me dé!\n¡Bendita sea el hacha, bendita la red,\ny loadas sean tijeras y sed!\n\nSangre del costado\nmanaré, mi amado.\n¿Qué broche más bello, qué joya más grata,\nque por ti una llaga color escarlata?\n\nEn vez de abalorios para mis cabellos\nsiete espinas largas hundiré entre ellos.\nY en vez de zarcillos pondré en mis orejas,\ncomo dos rubíes, dos ascuas bermejas.\n\nMe verás reír\nviéndome sufrir.\nY tú llorarás.\nY entonces… ¡más mío que nunca serás!"},{"title":"El nido","year":"1895-1979","text":"Mi cama fue un roble \nY en sus ramas cantaban los pájaros \nMi cama fue un roble \nY mordió la tormenta sus gajos. \n\n….. Deslizo mis manos \nPor sus claros maderos pulidos, \nY pienso que acaso toco el mismo tronco \nDonde estuvo aferrado algún nido. \n\n…. Mi cama fue un roble. \nYo duermo en un árbol. \nEn un árbol amigo del agua, \nDel sol y la brisa del cielo y el musgo, \nDe lagartos de ojuelos dorados \nY de las orugas, de un verde esmeralda. \n\n…. Yo duermo en un árbol. \n¡Oh, amado!, en un árbol dormimos. \nAcaso por eso me parece el lecho \nEsta noche, blando y hondo cual nido. \n\n…. Y en ti me acurruco como una avecilla\nQue busca el reparo de su compañero. \n¡Que rezongue el viento, que gruña la lluvia! \nContigo en el nido, no sé lo que es miedo. \n\n… ¡Qué tristeza de muerte! ¡Qué las negras de queja\nBrotarían entonces! ¡Qué alas negras de queja\nEn lugar de las alas transparentes de abeja!"},{"title":"El pozo","year":"1895-1979","text":"Asiento de musgo florido\nsobre el viejo brocal derruido.\nSitio que elegimos para hablar de amor,\nbajo el enorme paraíso en flor.\n\n¡Ay, pobre del agua que del fondo mira,\ntal vez envidiosa, quizás dolorida!\n¡Tan triste la pobre, tan muda, tan quieta\nbajo esta nerviosa ramazón violeta!\n\n-Vámonos. No quiero que el agua nos vea\ncuando me acaricies. Tal vez eso sea\ndarle una tortura. ¿Quién la ama a ella?\n-Tonta! ¡Si de noche la besa una estrella!"},{"title":"Estío","year":"1895-1979","text":"Cantar del agua del río. \nCantar continuo y sonoro, \narriba bosque sombrío \ny abajo arenas de oro. \n\nCantar… \nde alondra escondida \nentre el oscuro pinar. \n\nCantar… \ndel viento en las ramas \nfloridas del retamar. \n\nCantar… \nde abejas ante el repleto \ntesoro del colmenar. \n\nCantar… \nde la joven tahonera \nque al río viene a lavar. \n\nY cantar, cantar, cantar \nde mi alma embriagada y loca \nbajo la lumbre solar."},{"title":"Fusión","year":"1895-1979","text":"Mi alma en torno a tu alma se ha hecho \nun nudo apretado y sombrío.\n\nCada vuelta del lazo sobre humano\nse hace raíz, para afianzarse hondo,\ny es un abrazo inacabable y largo\nque ni la muerte romperá. ¿No sientes\ncómo me nutro de tu misma sombra?\n\nMi raíz se ha trenzado a tus raíces\ny cuando quieras desatar el nudo,\nsentirás que te duele en carne viva\ny que en mi herida brota sangre tuya.!\n\nY con tus manos curarás la llaga\n¡y ceñirás más apretado el nudo!"},{"title":"Hora morada","year":"1895-1979","text":"¿Qué azul me queda?\n\n¿En qué oro y en qué rosa me detengo,\nqué dicha se hace miel entre mi boca\no qué río me canta frente al pecho?\n\nEs la hora de la hiel, la hora morada\nen que el pasado, como un fruto acedo,\nsólo me da su raso deslucido\ny una confusa sensación de miedo.\n\nSe me acerca la tierra del descanso\nfinal, bajo los árboles erectos,\nlos cipreses aquellos que he cantado\ny veo ahora en guardia de los muertos.\n\nAmé, ay Dios, amé a hombres y bestias\ny sólo tengo la lealtad del perro\nque aún vigila a mi lado mis insomnios\ncon sus ojos tan dulces y tan buenos."},{"title":"Implacable","year":"1895-1979","text":"Y te di el olor\nde todas mis dalias y nardos en flor.\n\nY te di el tesoro,\nde las ondas minas de mis sueños de oro.\n\nY te di la miel,\ndel panal moreno que finge mi piel.\n\n¡Y todo te di!\nY como una fuente generosa y viva para tu alma fui.\n\n¡Y tú, dios de piedra\nentre cuyas manos ni la yedra medra;\n\ny tú, dios de hierro,\nante cuyas plantas velé como un perro,\n\ndesdeñaste el oro, la miel y el olor.\n¡ Y ahora retornas, mendigo de amor,\n\na buscar las dalias, a implorar el oro,\na pedir de nuevo todo aquel tesoro!\n\nOye, pordiosero:\nahora que tú quieres es que yo no quiero.\n\nSi el rosal florece,\nes ya para otro que en capullos crece.\n\nVete, dios de piedra,\nsin fuentes, sin dalias, sin mieles, sin yedra,\nigual que una estatua,\na quien Dios bajara del plinto, por fatua.\n\n¡Vete, dios de hierro,\nque junto a otras plantas se ha tendido el perro!"},{"title":"La cita","year":"1895-1979","text":"Me he ceñido toda con un manto negro.\nEstoy toda pálida, la mirada extática.\nY en los ojos tengo partida una estrella.\n¡Dos triángulos rojos en mi faz hierática!\n\nYa ves que no luzco siquiera una joya,\nni un lazo rosado, ni un ramo de dalias.\nY hasta me he quitado las hebillas ricas\nde las correhuelas de mis dos sandalias.\n\nMas soy esta noche, sin oros ni sedas,\nesbelta y morena como un lirio vivo.\nY estoy toda ungida de esencias de nardos,\ny soy toda suave bajo el manto esquivo.\n\nY en mi boca pálida florece ya el trémulo\nclavel de mi beso que aguarda tu boca.\nY a mis manos largas se enrosca el deseo\ncomo una invisible serpentina loca.\n\n¡Descíñeme, amante! ¡Descíñeme, amante!\nBajo tu mirada surgiré como una\nestatua vibrante sobre un plinto negro\nhasta el que se arrastra, como un can, la luna."},{"title":"La enredadera","year":"1895-1979","text":"Por el molino del huerto\nAsciende una enredadera.\nEl esqueleto de hierro\nVa a tener un chal de seda\nAhora verde, azul más tarde\nCuando llegue el mes de Enero\nY se abran las campanillas\nComo puñados de cielo.\nAlma mía: ¡quién pudiera\nvestirte de enredadera!"},{"title":"La espera","year":"1895-1979","text":"¡Oh lino, madura, que quiero tejer\nsábanas del lecho donde dormirá\nmi amante, que pronto, pronto tornará\n(Con la primavera tiene que volver.)\n\n¡Oh rosa, tu prieto capullo despliega!\nHas de ser el pomo que arome su estancia.\nConcentra colores, recoge fragancia,\ndilata tus poros, que mi amante llega.\n\nTrabaré con grillo de oro sus piernas,\ncadenas livianas del más limpio acero,\nencargué con prisa, con prisa al herrero\nAmor, que las hace brillantes y eternas.\n\nY sembré amapolas en toda la huerta.\n¡Que nunca recuerde caminos ni sendas!\nFatiga: en sus nervios aprieta tus vendas.\nMolicie: sé el perro que guarde la puerta."},{"title":"La estrella","year":"1895-1979","text":"Puño cerrado de la tormenta\ncontra la clara mejilla de luz.\nLa tarde hoy no tendrá el collar de júbilo de mi risa\nni el horizonte ha de endulzarse con un filo azul.\n\nRamazón ardida del relámpago\nsobre el despeluzado cardal del mar.\n\nEn el dibujo de Doré\nsoy un alma que espera la última barca\ny aprieta entre sus manos el sueño puro y silencioso\nque tendrá para el barquero el valor de un óbulo de plata.\n\nHe de esperarte siempre más allá de la vida\ny más allá del aire y de la sed.\n\nLa esperanza de verte llegar\nmullirá mi tiniebla.\n\nY en la proa de la barca empavonada de sombra,\ncomo una fulgurante bordadura de seda,\nmi terco ensueño ha de cuajar para la noche de tu tránsito\nlos cinco pétalos menudos de una estrella."},{"title":"La higuera","year":"1895-1979","text":"Porque es áspera y fea,\nporque todas sus ramas son grises,\nyo le tengo piedad a la higuera.\n\nEn mi quinta hay cien árboles bellos:\nciruelos redondos, \nlimoneros rectos\ny naranjos de brotes lustrosos.\n\nEn las primaveras,\ntodos ellos se cubren de flores\nen torno a la higuera.\n\nY la pobre parece tan triste\ncon sus gajos torcidos que nunca\nde apretados capullos se visten…\n\nPor eso,\ncada vez que yo paso a su lado,\ndigo, procurando\nhacer dulce y alegre mi acento:\n-Es la higuera el más bello\nde los árboles en el huerto.\n\nSi ella escucha,\nsi comprende el idioma en que hablo,\n¡qué dulzura tan honda hará nido\nen su alma sensible de árbol!\n\nY tal vez a la noche,\ncuando el viento abanique su copa,\nembriagada de gozo, le cuente:\n-Hoy a mi me dijeron hermosa."},{"title":"La hora","year":"1895-1979","text":"Tómame ahora que aun es temprano\ny que llevo dalias nuevas en la mano.\n\nTómame ahora que aun es sombría\nesta taciturna cabellera mía.\n\nAhora que tengo la carne olorosa\ny los ojos limpios y la piel de rosa.\n\nAhora que calza mi planta ligra\nla sandalia viva de la primavera.\n\nAhora que mis labios repica la risa\ncomo una campana sacudida a prisa.\n\nDespués…, ¡ah, yo sé\nque ya nada de eso mas tarde tendré!\n\nQue entonces inútil será tu deseo,\ncomo ofrenda puesta sobre un mausoleo.\n\n¡Tómame ahora que aun es temprano\ny que tengo rica de nardos la mano!\n\nHoy, y no mas tarde. Antes que anochezca\ny se vuelva mustia la corola fresca.\n\nHoy, y no mañana. ¡Oh amante! ¿no ves\nque la enredadera crecerá ciprés?"},{"title":"La inquietud fugaz","year":"1895-1979","text":"He mordido manzanas y he besado tus labios.\nMe he abrazado a los pinos olorosos y negros.\nHundí, inquieta, mis manos en el agua que corre.\nHe huroneado en la selva milenaria de cedros\nque cruza la pradera como una serpie grave,\ny he corrido por todos los pedrosos caminos\nque ciñen como fajas la ventruda montaña.\n\n¡Oh amado, no te irrites por mi inquietud sin tregua!\n¡Oh amado, no me riñas porque cante y me ría!\nHa de llegar un día en que he de estarme quieta,\n¡ay, por siempre, por siempre!\ncon las manos cruzadas y apagados los ojos;\ncon los oídos sordos y con la boca muda,\ny los pies andariegos en reposo perpetuo\nsobre la tierra negra.\n¡Y estará roto el vaso de cristal de mi risa\nEn la grieta obstinada de mis labios cerrados!\n\nEntonces, aunque digas: -¡Anda!, ya no andaré.\nY aunque me digas: -¡Canta!, no volveré a cantar.\nMe iré desmenuzando en quietud y en silencio\nbajo la tierra negra,\nmientras encima mío se oirá zumbar la vida\ncomo una abeja ebria.\n\n¡Oh, déjame que guste el dulzor del momento\nfugitivo e inquieto!\n\n¡Oh, deja que la rosa desnuda de mi boca\nse te oprima a los labios!\n\nDespués será ceniza sobre la tierra negra."},{"title":"La pasajera","year":"1895-1979","text":"Va la tarde subiendo hacia la noche,\nRío opulento y cálido,\nCon olor de duraznos y de rosas,\nCon rumores de risas y de llantos,\nCon el jadeo del miedo,\nCon la espiral del canto.\n\n   Navío empavesado que me lleva\nA la elevada, misteriosa sombra,\nSin nadie que me ciña la cintura\nCon poderosa mano protectora.\n\n   Erguida estoy, sin voz y sin sonrisa,\nBlanca en la inmensa soledad nocturna,\nCon la brasa del verso en la garganta\nY en el pecho la sed de la aventura.\n\n   Las últimas magnolias del verano\nSon el claro escabel de mi fatiga.\nLa deshilada llama del crepúsculo\nAun se mantiene viva\nEn la secreta red de las arterias.\nVoy al encuentro de las tres Marías.\n\n   Ah qué triste, qué calma y valerosa\nEsta mujer que asciende hasta la noche\nSin un temblor, y sola cual si fuese\nLa pasajera única e insomne.\n\n   Sabe de los encuentros con fantasmas,\nCon los ardidos filos del recuerdo\nY las angustias del dolor humano,\nRizadura del grito en el silencio.\n\n   Ha de arribar a la mañana nueva\nDesmadejada por el sufrimiento.\nComo si hubiera estado en los crisoles\nDonde se funde el clamor y el miedo.\n\n   Y bajará llorando de la nave\nPorque no pudo vislumbrar el cielo."},{"title":"La pequeña llama","year":"1895-1979","text":"Yo siento por la luz un amor de salvaje.\nCada pequeña llama me encanta y sobrecoge;\n¿no será, cada lumbre, un cáliz que recoge\nel calor de las almas que pasan en su viaje?\n\nHay unas pequeñitas, azules, temblorosas,\nlo mismo que las almas taciturnas y buenas.\nHay otras casi blancas: fulgores de azucenas.\nHay otras casi rojas: espíritus de rosas.\n\nYo respeto y adoro la luz como si fuera\nuna cosa que vive, que siente, que medita,\nun ser que nos contempla transformado en hoguera.\n\nAsí, cuando yo muera, he de ser a tu lado\nuna pequeña llama de dulzura infinita\npara tus largas noches de amante desolado."},{"title":"La primavera","year":"1895-1979","text":"Como un ala negra tendí mis cabellos\n sobre tus rodillas.\n Cerrando los ojos su olor aspiraste\n diciéndome luego:\n ¿Duermes sobre piedras cubiertas de musgos?\n ¿Con ramas de sauces te atas las trenzas?\n ¿Tu almohada es de trébol? ¿Las tienes tan negras\n porque acaso en ellas exprimiste un zumo\n retinto y espeso de moras silvestres?\n .\n ¡Qué fresca y extraña fragancia te envuelve!\n Hueles a arroyuelos, a tierra y a selvas.\n ¿Qué perfume usas? Y riendo le dije:\n -¡Ninguno, ninguno!\n Te amo y soy joven, huelo a primavera.\n .\n Este olor que sientes es de carne firme,\n de mejillas claras y de sangre nueva.\n ¡Te quiero y soy joven, por eso es que tengo\n las mismas fragancias de la primavera!"},{"title":"La promesa","year":"1895-1979","text":"¡Todo el oro del mundo parecía\ndiluído en la tarde luminosa!\nApenas un crepúsculo de rosa,\nla copa de los árboles teñía.\n\nUn imprevisto amor, mi mano unía\na tu mano, morena y temblorosa.\n¡Eramos Booz y Ruth ante la hermosa\nera que circundaba la alquería!\n\n\"¿Me amarás?\", murmuraste. Lenta y grave\nvibró en mis labios la promesa suave\nde la dulce, la amante moabita.\n\nY fué como un ¡Amén! en ese instante\nel toque de oración que alzó vibrante\nla rítmica campana de la ermita."},{"title":"La sed","year":"1895-1979","text":"Tu beso fue en mis labios\nde un dulzor refrescante.\nSensación de agua viva y moras negras\nme dio tu boca amante.\n\nCansada me acosté sobre los pastos\ncon tu brazo tendido, por apoyo.\nY me cayó tu beso entre los labios,\ncomo un fruto maduro de la selva\no un lavado guijarro del arroyo.\n\nTengo sed otra vez, amado mío.\nDame tu beso fresco tal como una\npiedrezuela del río."},{"title":"La tarde","year":"1895-1979","text":"He bebido del chorro cándido de la fuente.\nTraigo los labios frescos y la cara mojada.\nMi boca hoy tiene toda la estupenda dulzura\nde una rosa jugosa, nueva y recién cortada.\n\nEl cielo ostenta una limpidez de diamante.\nEstoy ebria de tarde, de viento y primavera.\n¿No sientes en mis trenzas olor a trigo ondeante?\n¿No me hallas hoy flexible como una enredadera?\n\nElástica de gozo como un gamo he corrido\npor todos los ceñudos senderos de la sierra.\nY el galgo cazador que es mI guía, rendido,\nse ha acostado a mis pies, largo a largo, en la tierra.\n\n¡Ah, qué inmensa fatiga me derriba en la grama\nY abate en tus rodillas mi cabeza morena,\nmientras que de una iglesia campesina y lejana\nnos llega un lento y grave llamado de novena!"},{"title":"Lacería","year":"1895-1979","text":"No codicies mi boca. Mi boca es de ceniza\ny es un hueco sonido de campanas mi risa.\n\nNo me oprimas las manos. Son de polvo mis manos,\ny al estrecharlas tocas comida de gusanos.\n\nNo trences mis cabellos. Mis cabellos son tierra\ncon la que han de nutrirse las plantas de la sierra.\n\nNo acaricies mis senos. Son de greda los senos\nque te empeñas en ver como lirios morenos.\n\n¿Y aún me quieres, amado? ¿Y aún mi cuerpo pretendes\ny, largas de deseo, las manos a mí tiendes?\n\n¿Aún codicias, amado, la carne mentirosa\nque es ceniza y se cubre de apariencias de rosa?\n\nBien, tómame. ¡Oh laceria!\n¡Polvo que busca al polvo sin sentir su miseria!"},{"title":"Las cuatro alas de abeja","year":"1895-1979","text":"He vuelto de la cita con cuatro alas de abejas\nprendidas en los labios. Cuatro alas de abejas\ndoradas y bermejas.\n\nMilagro como el de la barba de Dionisos,\nel dios de acento dulce! La barba de Dionisos\nque tenía cuatro alas de abeja en vez de rizos.\n\nTus labios en mis labios derramaron su miel\ny brotaron las alas. Derramaron su miel\ny tuve las dulzuras de un panal en la piel.\n\nNo riáis. Las cuatro alas de abeja no se ven.\nMas las siento en la boca. Las alas no se ven,\nmas a veces, ¡prodigio!, vibran hasta en mi sien.\n\nY más adentro aún. Las dulces alas vibran\nhasta en mi corazón. Las dulces alas vibran\ny a mi alma de toda angustia y pena libran.\n\nMas si un día dejaran de aletear y zumbar…\nsi se hicieran ceniza… Si cesara el zumbar\nde las alas que hiciste en mis labios brotar…\n\n¡Qué tristeza de muerte! ¡Qué alas negras de queja\nbrotarían entonces! ¡Qué alas negras de queja\nen lugar de las alas transparentes de abeja!"},{"title":"Las lenguas de diamante","year":"1895-1979","text":"Bajo la luna llena, que es una oblea de cobre,\nVagamos taciturnos en un éxtasis vago,\nComo sombras delgadas que se deslizan sobre\nLas arenas de bronce de la orilla del lago.\nSilencio en nuestros labios una rosa ha florido.\n¡Oh, si a mi amante vencen tentaciones de hablar!,\nLa corola, deshecha, como un pájaro herido,\ncaerá, rompiendo el suave misterio sublunar.\n¡Oh dioses, que no hable! ¡Con la venda más fuerte\nque tengáis en las manos, su acento sofocad!\n¡Y si es preciso, el manto de piedra de la muerte\npara formar la venda de su boca, rasgad!\nYo no quiero que hable. Yo no quiero que hable.\nSobre el silencio éste, ¡qué ofensa la palabra!\n¡Oh lengua de ceniza! ¡Oh lengua miserable,\nno intentes que ahora el sello de mis labios te abra!\nBajo la luna-cobre, taciturnos amantes, \nCon los ojos gimamos, con los ojos hablemos.\nSerán nuestras pupilas dos lenguas de diamantes\novidas por la magia de diálogos supremos."},{"title":"Las olas","year":"1895-1979","text":"Si todas las gaviotas de esta orilla\nQuisieran unir sus alas, \nY formar el avión o la barca\nQue pudiesen llevarme hasta otras playas…\nBajo la noche enigmática y espesa\nViajaríamos rasando las aguas.\nCon un grito de triunfo y de arribo\nMis gaviotas saludarían el alba.\nDe pie sobre la tierra desconocida\nno tendería al nuevo sol las manos\nomo si fueran dos alas recién nacidas.\n¡Dos alas con las que habría de ascender\nHasta una nueva vida!"},{"title":"Lo que soy para ti","year":"1895-1979","text":"Cierva,\nQue come en tus manos la olorosa hierba.\nCan,\nQue sigue tus pasos doquiera que van.\nEstrella,\nPara ti poblada de sol y centella.\nFuente,\nQue a tus pies ondula como una serpiente.\nFlor,\nQue para ti solo da mieles y olor.\nTodo eso yo soy para ti,\nMi alma en todas sus formas te dí.\nCierva y can, astro y flor, \nAgua viva que glisa a tus pies,\nMi alma es\nPara ti, \nAmor."},{"title":"Melancolía","year":"1895-1979","text":"La sutil hilandera teje su encaje oscuro\ncon ansiedad extraña, con paciencia amorosa.\n¡Qué prodigio si fuera hecho de lino puro\ny fuera, en vez de negra la araña, color rosa!\n\nEn un rincón del huerto aromoso y sombrío\nla velluda hilandera teje su tela leve.\nEn ella sus diamantes suspenderá el rocío\ny la amarán la luna, el alba, el sol, la nieve.\n\nAmiga araña: hilo cual tú mi velo de oro\ny en medio del silencio mis joyas elaboro.\nNos une, pues, la angustia de un idéntico afán.\n\nMas pagan tu desvelo la luna y el rocío.\n¡Dios sabe, amiga araña, qué hallaré por el mío!\n¡Dios sabe, amiga araña, qué premio me darán!"},{"title":"Millonarios","year":"1895-1979","text":"Tómame de la mano. Vámonos a la lluvia\ndescalzos y ligeros de ropa, sin paraguas,\ncon el cabello al viento y el cuerpo a la caricia\noblicua, refrescante y menuda, del agua.\n\n¡Que rían los vecinos! Puesto que somos jóvenes\ny los dos nos amamos y nos gusta la lluvia,\nvamos a ser felices con el gozo sencillo\nde un casal de gorriones que en la vía se arrulla.\n\nMás allá están los campos y el camino de acacias\ny la quinta suntuosa de aquel pobre señor\nmillonario y obeso, que con todos sus oros,\n\nno podría comprarnos ni un gramo del tesoro\ninefable y supremo que nos ha dado Dios:\nser flexibles, ser jóvenes, estar llenos de amor."},{"title":"Noche de lluvia","year":"1895-1979","text":"Llueve… Espera, no duermas,\nestáte atento a lo que dice el viento\ny a lo que dice el agua que golpea\ncon sus dedos menudos en los vidrios.\n\n¡Cómo estará de alegre el trigo ondeante!\n¡Con qué avidez se esponjará la hierba!\n¡Cuántos diamantes colgarán ahora\ndel ramaje profundo de los pinos!\n\nEspera, no te duermas. Escuchemos\nel ritmo de la lluvia.\nApoya entre mis senos\ntu frente taciturna.\nYo sentiré el latir de tus dos sienes\npalpitantes y tibias,\ncomo si fueran dos martillos vivos\nque golpearan mi carne.\n\nEspera, no te duermas. Esta noche\nsomos los dos un mundo,\naislado por el viento y por la lluvia\nentre la cuenca tibia de una alcoba.\n\nEspera, no te duermas. Esta noche \nsomos acaso la raíz suprema\nde donde debe germinar mañana\nel tronco bello de una raza nueva."},{"title":"Olor frutal","year":"1895-1979","text":"Con membrillos maduros \nPerfumo los armarios. \nTiene toda mi ropa\nUn aroma frutal que da a mi cuerpo\nUn constante sabor a primavera. \nCuando de los estantes\nPulidos y profundos\nSaco un brazado blanco\nDe ropa íntima, \nPor el cuarto se esparce\nUn ambiente de huerto. \n\n¡Parece que tuviera en mis armarios\nPreso el verano! \nEse perfume es mío. Besarás mil mujeres\nJóvenes y amorosas, mas ninguna\nTe dará esa impresión de amor agreste\nQue yo te doy. \n\nPor eso, en mis armarios\nGuardo frutas maduras, \nY entre los pliegues de la ropa íntima\nEscondo, con manojos secos de vetiver. \nMembrillos redondos y pintones. \n\nMi piel está impregnada\nDe esta fragancia viva; \nBesarás mil mujeres, mas ninguna\nTe dará esta impresión de arroyo y selva\nQue yo te doy."},{"title":"Panteísmo","year":"1895-1979","text":"Siento un acre placer en tenderme en la tierra,\nbajo el sol matutino tibia como una cama.\nBajo mi cuerpo, ¡cuánta vida mi vientre encierra!\n¡Quién sabe qué diamante esconde aquí su llama!\n\n¡Quién sabe qué tesoro, dentro de una mirada,\nsurgirá de este mismo lugar donde reposo,\nsi será el oro vivo de una era sembrada,\no la viva esmeralda de algún árbol frondoso!\n\n¡Quién sabe qué estupenda y dorada simiente\nha de brotar ahora bajo mi cuerpo ardiente!\nFuturo pebetero que esparcirá a los vientos,\nen las noches de estío, claras y rumorosas,\nel calor de mi carne hecho aroma de rosas,\nfragancia de azucenas, y olor de pensamientos."},{"title":"Raíz salvaje","year":"1895-1979","text":"Me ha quedado clavada en los ojos\nla visión de ese carro de trigo\nque cruzó rechinante y pesado\nsembrando de espigas el recto camino.\n\n¡No pretendas ahora que ría!\n¡Tu no sabes en qué hondos recuerdos\nestoy abstraída!\n\nDesde el fondo del alma me sube\nun sabor de pitanga a los labios.\nTiene aún mi epidermis morena\nno sé que fragancias de trigo emparvado.\n\n¡Ay, quisiera llevarte conmigo\na dormir una noche en el campo\ny en tus brazos pasar hasta el día\nbajo el techo alocado de un árbol!\n\nSoy la misma muchacha salvaje\nque hace años trajiste a tu lado."},{"title":"Rebelde","year":"1895-1979","text":"Caronte: yo seré un escándalo en tu barca.\nMientras las otras sombras recen, giman o lloren,\ny bajo tus miradas de siniestro patriarca\nlas tímidas y tristes, en bajo acento, oren,\n\nYo iré como una alondra cantando por el río\ny llevaré a tu barca mi perfume salvaje,\ne irradiaré en las ondas del arroyo sombrío\ncomo una azul linterna que alumbrara en el viaje.\n\nPor más que tú no quieras, por más guiños siniestros\nque me hagan tus dos ojos, en el terror maestros,\nCaronte, yo en tu barca seré como un escándalo.\n\nY extenuada de sombra, de valor y de frío,\ncuando quieras dejarme a la orilla del río\nme bajarán tus brazos cual conquista de vándalo."},{"title":"Reconquista","year":"1895-1979","text":"No sé de donde regresó el anhelo\nDe volver a cantar como en el tiempo\nen que tenía entre mi puño el cielo\nY con una perla azul el pensamiento.\n\nDe una enlutada nube, la centella,\nSúbito pez, hendió la noche cálida\nY en mí se abrió de nuevo la crisálida\nDel verso alado y su bruñida estrella.\n\nAhora ya es el hino centelleante\nQue alza hasta Dios la ofrenda poderosa\nDe su bruñida lanza de diamante.\n\nUnidad de la luz sobre la rosa.\nY otra vez la conquista alucinante\nDe la eterna poesía victoriosa."},{"title":"Regreso","year":"1895-1979","text":"¿En qué silente cinturón de espuma\nse oculta ahora la promesa yerta?\n¿Tras de qué muro o entornada puerta\ngime mi mundo?\n\n¿Qué hora, qué mañana entre tumultos\nde sol y risa, ya de cara al gozo,\nme traerá su jazmín más primoroso\ncon la sortija mágica del rumbo?\n\nSe quemó mi laurel entre la fiebre,\nla palma fiel perdió su airón de fuego.\nYa sólo soy raíz, rígido ruego,\nvástago de espiral lenta y endeble.\n\nPero yo me he de alzar del pudridero,\nvolveré a mi esplendor de carne y canto,\nblanca y bruñida por mi propio llanto,\nviva, de nuevo."},{"title":"Salvaje","year":"1895-1979","text":"Bebo del agua limpia y clara del arroyo\ny vago por los campos teniendo por apoyo\nun gajo de algarrobo liso, fuerte y pulido\nque en sus ramas sostuvo la dulzura de un nido.\n\nAsí paso los días, morena y descuidada,\nsobre la suave alfombra de la grama aromada.\nComiendo de la carne jugosa de las fresas\no en busca de fragantes racimos de frambuesas.\n\nMi cuerpo está impregnado del aroma ardoroso\nde los pastos maduros. Mi cabello sombroso\nesparce, al destrenzarlo, olor a sol y a heno,\na savia, a yerbabuena y a flores de centeno.\n\n¡Soy libre, sana, alegre, juvenil y morena,\ncual si fuera la diosa del trigo y de la avena!\n¡Soy casta como Diana\ny huelo a hierba clara nacida en la mañana!"},{"title":"Septiembre","year":"1895-1979","text":"Primavera labradora \n—aire hilado, surco en flor—.\nEn el alba, trinadora;\nbuena abeja bajo el sol,\ny en las noches de violeta\nesperanza y resplandor.\n\nPrimavera labradora:\n¡Recibe bien a mi amor!\n\nLleva los hombros curvados\ndel afán de la ciudad\ny en los labios la salmuera \nde los vientos de la mar. \n\nSeptiembre, mes campesino:\n¡Sé tibio, rico y floral! \n\nRecorta tus manzanillas;\nbruñe tu luna de plata;\nacuña entre piedrazuelas,\nbien redondeadas y claras,\nlos musgos recién nacidos\nen la orillita del agua.\n\n¡Que el mundo parezca nuevo\nalrededor del que quiero!;\nsombra y sol para su día,\ndulzura para su sueño,\ny en el sueño —heliótropo \ndel terciopelo—, el recuerdo\n\nSeptiembre que multiplicas\nlos corderos y los peces: \n\n¡Multiplícame su amor\nbajo tu signo celeste! ."},{"title":"Sueño?","year":"1895-1979","text":"Beso que ha mordido mi carne y mi boca\nCon su mordedura que hasta el alma toca!\n¡Beso que me sorbe lentamente vida, \ncomo una incurable y ardorosa herida!\n¡Fuego que me quema sin mostrar la llama\ny que a todas horas por más fuego clama!\n¿Fue una boca bruja o un labio hechizado\nel que con su beso mi alma ha llagado?\n¿Fue en sueño o vigilia que hasta mí llegó\nel que entre sus labios mi alma estrujó?\nCalzaré sandalias de bronce e iré.\nAdonde esté el mago que cura me dé.\n¡Secadme esta llaga, vendadme esta herida\nque por ella en fuga se me va la vida!"},{"title":"Supremo triunfo","year":"1895-1979","text":"Estoy ahora impregnada toda yo de dulzura.\nDesde que me besaste, toda yo soy amor.\nY en la vida y la muerte, en lecho y sepultura,\nya no seré otra cosa que amor, amor, amor….\n\nEn la carne y el alma, en la sombra y los huesos,\nya no tendré más nunca otro olor y sabor,\nque el sabor y el perfume que he absorbido a tus besos;\nme has dado una fragancia, tersa y viva, de flor.\n\nHasta el último átomo de mi piel es aroma,\n¡oh mortal podredumbre, te he vencido talvez!\nEres mi hermano , ¡Oh lirio! Eres mi hermana ¡oh poma!\nDesde que él me besara, rosa mi cuerpo es."},{"title":"Te doy mi alma desnuda","year":"1895-1979","text":"Te doy mi alma desnuda,\ncomo estatua a la cual ningún cendal escuda.\n\nDesnuda con el puro impudor\nde un fruto, de una estrella o una flor;\nde todas esas cosas que tienen la infinita\nserenidad de Eva antes de ser maldita.\n\nDe todas esas cosas,\nfrutos, astros y rosas,\nque no sienten vergüenza del sexo sin celajes\ny a quienes nadie osara fabricarles ropajes.\n\nSin velos, como el cuerpo de una diosa serena\n¡que tuviera una intensa blancura de azucena!\n\nDesnuda, y toda abierta de par en par\n¡por el ansia del amar!"},{"title":"Toilette-suprema","year":"1895-1979","text":"Bajo el encanto sombrío\nde la tarde de tormenta\nhay trazos de luz violenta\nen la amatista del río.\nY siento la tentación\nde hundir mi cuerpo en la oscura\nagua quieta que fulgura\nbajo el cielo de crespón.\n\nIntensa coquetería\ndel contraste con la onda\nque hará mi carne más blonda\nentre su gasa sombría.\nRara y divina «toalé«\nque en la penumbra amatista\ndará una gracia imprevista\na mi cuerpo rosa-té.\n\nNinguna tela más bella\nEn su pliegue ha de envolverme.\n¡Nunca tornarás a verme\nCon tal blancura de estrella!\nJamás caprichoso azar\nha dado, a ninguna amante,\nun lecho más fulgurante\nbajo el amado mirar.\n\nDeja que el río me vista\ncon sus largos pliegues lilas,\ny guarda en tus dos pupilas,\njunto al fondo de amatista,\nla visión loca y suprema\nde mi cuerpo embellecido\npor el oscuro vestido\ny la sombría diadema."},{"title":"Vida - garfio","year":"1895-1979","text":"Amante: no me lleves, si muero al camposanto\nA flor de tierra abre mi fosa, junto al riente\nalboroto divino de alguna pajarera\no junto a la encantada charla de alguna fuente\n\nA flor de tierrra, amante. Casi sobre la tierra,\ndonde el sol me caliente los huesos, y mis ojos,\nalargados en tallos, suban a ver de nuevo\nla lámpara salvaje de los ocasos rojos.\n\nA flor de tierra, amante. Que el tránsito así sea\nmás breve. Yo presiento\nla lucha de mi carne por volver hacia arriba,\npor sentir en sus átomos la frescura del viento.\n\nYo se que acaso nunca allá abajo mis manos\npodrán estarse quietas.\nQue seimpre como topos arañarán la tierra\nen medio de las sombras estrujadas y prietas.\n\nArrójame semillas. Yo quiero que se enraícen\nen la greda amarilla de mis huesos menguados.\n¡Por la parda escalera de las raices vivas\nYo subiré a mirarte en los lirios morados."},{"title":"Vida aldeana","year":"1895-1979","text":"Iremos por los campos, de la mano,\na través de los bosques y los trigos,\nentre rebaños cándidos y amigos,\nsobre la verde placidez del llano,\n\npara comer el fruto dulce y sano\nde las rústicas vides y los higos\nque coronan las tunas. Como amigos\npartiremos el pan, la leche, el grano.\n\nY en las mágicas noches estrelladas,\nbajo la calma azul, entrelazadas\nlas manos, y los labios temblorosos,\n\nrenovaremos nuestro muerto idilio,\ny será como un verso de Virgilio\nvivido ante los astros luminosos."},{"title":"¡Cómo resbala el agua por mi espalda!","year":"1895-1979","text":"¡Cómo resbala el agua por mi espalda!\n ¡Cómo moja mi falda\n y pone en mis mejillas su frescura de nieve!\n Llueve, llueve, llueve.\n Y voy, senda adelante,\n con el alma ligera y la cara radiante.\n Sin sentir, sin soñar,\n llena de la voluptuosidad de no pensar\n Un pájaro se baña\n en una charca turbia. Mi presencia le extraña.\n Se detiene… Me mira… Nos sentimos amigos…\n ¡Los dos amamos mucho cielos, campos y trigos!\n Después es el asombro\n de un labriego que pasa con su azada en el hombro.\n Y la lluvia me cubre\n de todas las fragancias que a los setos da Octubre.\n Y es, sobre mi cuerpo por el agua empapado,\n como un maravilloso y estupendo tocado\n de gotas cristalinas, de flores deshojadas\n que vuelcan a mi paso las plantas asombradas.\n Y siento, en la vacuidad\n del cerebro sin sueños, la voluptuosidad\n del placer infinito, dulce y desconocido,\n de un minuto de olvido.\n Llueve, llueve, llueve,\n y tengo, en alma y carne, como un frescor de nieve."}],"topPainters":[{"dir":"okeeffe","name":"Georgia O’Keeffe","value":0.277288,"best":0.343458},{"dir":"monet","name":"Claude Monet","value":0.246594,"best":0.310313},{"dir":"sorolla","name":"Joaquín Sorolla","value":0.256488,"best":0.306368}],"topPairs":[{"pintor":"okeeffe","obra":"01_jimson_weed.jpg","poeta":"Ibarbourou, Juana de","sim":0.398012,"p":50},{"pintor":"sorolla","obra":"06_fishermen_wives.jpg","poeta":"Ibarbourou, Juana de","sim":0.397264,"p":35},{"pintor":"monet","obra":"06_japanese_bridge.jpg","poeta":"Ibarbourou, Juana de","sim":0.39475,"p":51}]},{"name":"Walt Whitman","gender":"Hombre","period":"Poesía trascendentalista, siglo XIX","region":"Estados Unidos","profile":null,"poems":[{"title":"Song of Myself (excerpts)","year":"1855","text":"I celebrate myself, and sing myself,\nAnd what I assume you shall assume,\nFor every atom belonging to me as good belongs to you.\n\nI loafe and invite my soul,\nI lean and loafe at my ease observing a spear of summer grass.\n\nMy tongue, every atom of my blood, form'd from this soil, this air,\nBorn here of parents born here from parents the same, and their parents the same,\nI, now thirty-seven years old in perfect health begin,\nHoping to cease not till death.\n\nCreeds and schools in abeyance,\nRetiring back a while sufficed for what they are, but never forgotten,\nI harbor for good or bad, I permit to speak at every hazard,\nNature without check with original energy.\n\nThe atmosphere is not a perfume, it has no taste of the distillation, it is odorless,\nIt is for my mouth forever, I am in love with it,\nI will go to the bank by the wood and become undisguised and naked,\nI am mad for it to be in contact with me.\n\nThe smoke of my own breath,\nEchos, ripples, buzz'd whispers, love-root, silk-thread, crotch and vine,\nMy respiration and inspiration, the beating of my heart, the passing\n    help and blood through the lungs,\nThe sniff of green leaves and dry leaves, and of the shore and\n    dark-color'd sea-rocks, and of hay in the barn,\nThe sound of the belch'd words of my voice loos'd to the eddies of the wind,\nA few light kisses, a few embraces, a reaching around of arms,\nThe play of shine and shade on the trees as the supple boughs wag,\nThe delight alone or in the rush of the streets, or along the fields and\n    hill-sides,\nThe feeling of health, the full-noon trill, the song of me rising from bed\n    and meeting the sun.\n\nI loafe and invite my soul,\nI lean and loafe at my ease observing a spear of summer grass.\n\nYou shall no longer take things at second or third hand, nor look through\n    the eyes of the dead, nor feed on the spectres in books,\nYou shall not look through my eyes either, nor take things from me,\nYou shall listen to all sides and filter them from your self."},{"title":"I Sing the Body Electric","year":"1855","text":"I sing the body electric,\nThe armies of those I love engirth me and I engirth them,\nThey will not let me off till I go with them, respond to them,\nAnd discorrupt them, and charge them full with the charge of the soul.\n\nWas it doubted that those who corrupt their own bodies conceal themselves?\nAnd if those who defile the living are as bad as they who defile the dead?\nAnd if the body does not do fully as much as the soul?\nAnd if the body were not the soul, what is the soul?\n\nThe anatomy of the body electric:\n1 The face, forehead, neck, back, sides, joints, muscles, arms, hands, chest,\n    belly, loins, thighs, knees, legs, feet, ankles, toes,\n2 The brain and its parts, the skull, the eyes, the mouth, the tongue,\n    teeth, lips, nose, cheeks, ears, hair,\n3 The heart and its parts, the blood, the veins, the arteries,\n4 The lungs, the stomach, the liver, the spleen,\n5 The reproductive organs and their parts,\n6 The skin, the nerves, the bones."},{"title":"I Hear America Singing","year":"1860","text":"I hear America singing, the varied carols I hear,\nThose of mechanics, each one singing his as it should be blithe and strong,\nThe carpenter singing his as he measures his plank or beam,\nThe mason singing his as he makes ready for work, or leaves off work,\nThe boatman singing what belongs to him in his boat, the deckhand singing on the steamboat deck,\nThe shoemaker singing as he sits on his bench, the hatter singing as he stands,\nThe wood-cutter's song, the ploughboy's on his way in the morning, or at noon intermission or at sundown,\nThe delicious singing of the mother, or of the young wife at work, or of the girl sewing or washing,\nEach singing what belongs to him or her and to none else,\nThe day what belongs to the day—at night the party of young fellows, robust, friendly,\nSinging with open mouths their strong melodious songs."},{"title":"O Captain! My Captain!","year":"1865","text":"O Captain! my Captain! our fearful trip is done,\nThe ship has weather'd every rack, the prize we sought is won,\nThe port is near, the bells I hear, the people all exulting,\nWhile follow eyes the steady keel, the vessel grim and daring;\nBut O heart! heart! heart!\nO the bleeding drops of red,\nWhere on the deck my Captain lies,\nFallen cold and dead.\n\nO Captain! my Captain! rise up and hear the bells;\nRise up—for you the flag is flung—for you the bugle trills,\nFor you bouquets and ribbon'd wreaths—for you the shores a-crowding,\nFor you they call, the swaying mass, their eager faces turning;\nHere Captain! dear father!\nThis arm beneath your head!\nIt is some dream that on the deck,\nYou've fallen cold and dead.\n\nMy Captain does not answer, his lips are pale and stiff,\nMy father does not feel my arm, he has no pulse nor will,\nThe ship is anchor'd safe and sound, its voyage closed and done,\nFrom fearful trip the victor ship comes in with object won;\nExult O shores, and ring O bells!\nBut I with mournful tread,\nWalk the deck my Captain lies,\nFallen cold and dead."},{"title":"When Lilacs Last in the Dooryard Bloom'd (excerpts)","year":"1865","text":"When lilacs last in the dooryard bloom'd,\nAnd the great star early droop'd in the western sky in the night,\nI mourn'd, and yet shall mourn with ever-returning spring.\n\nO ever-returning spring, trinity sure to me you bring,\nLilac blooming perennial and deathless star of grass,\nAnd pencil of cedar and pine and bittersweet, and balm of the evergreen.\n\nIn the dooryard front of an old farm-house near the white-wash'd palings,\nStands the lilac-bush tall-growing with heart-shaped leaves of rich green,\nWith many a pointed blossom rising delicate, with the perfume strong I love,\nWith every leaf a miracle; and from this bush in the dooryard,\nWith delicate-colored blossoms and heart-shaped leaves of rich green,\nA sprig with its flower I break.\n\n\nNow do I know it!\nNow there is one man in all the world I can claim!\n\nSing on, sing on, sweet bird!\nSing on, sing on, sweet bird!\n\nI hear you, I hear you,\nI have heard you, I have heard you,\nI have heard you, I have heard you,\nSweet bird!\nI hear you, I hear you,\nI have heard you, I have heard you,\nSweet bird!\nI hear you, I hear you."},{"title":"A Noiseless Patient Spider","year":"1868","text":"A noiseless, patient spider,\nI mark'd where it stood on a little promontory, isolated,\nMark'd how to explore the vacant, vast surrounding,\nIt launch'd forth filament, filament, filament out of itself,\nEver unreeling them—ever tirelessly speeding them.\n\nAnd you O my soul where you stand,\nSurrounded, surrounded, in measureless oceans of space,\nCeaselessly musing, venturing, throwing,—seeking the spheres to connect them,\nTill the bridge you will need be form'd, till the ductile anchor hold,\nTill the gossamer thread you fling catch somewhere, O my soul."},{"title":"O Me! O Life!","year":"1855","text":"O me! O life! of the questions of these recurring,\nOf the endless trains of the faithless, of cities fill'd with the foolish,\nWhat good amid these, O me, O life?\n\nAnswer.\nThat you are here—that life exists and identity,\nThat the powerful play goes on, and you may contribute a verse."},{"title":"Song of the Open Road (excerpts)","year":"1856","text":"Afoot and light-hearted I take to the open road,\nHealthy, free, the world before me,\nThe long brown path before me leading wherever I choose.\n\nHenceforth I ask not good-fortune, I myself am good-fortune,\nHenceforth I whimper no more, postpone no more, need nothing,\nDone with indoor complaints, libraries, querulous criticisms,\nStrong and content I travel the open road.\n\nThe earth, that is sufficient,\nI do not want the constellations any nearer,\nI know they are very well where they are,\nI know they suffice for those who belong to them.\n\n(Still here I carry my old delicious burdens,\nI carry them, men and women, I press them to me and infuse them,\nI cannot be extruded from them,\nBut I will not carry them long.)\n\nAll seems beautiful to me,\nI can look up or down any road,\nI stop at it every day and every night,\nI am fill'd with ineffable contentment and peace."},{"title":"Out of the Cradle Endlessly Rocking","year":"1859","text":"Out of the cradle endlessly rocking,\nOut of the mocking-bird's throat, the musical shuttle,\nOut of the Ninth-month midnight,\nOver the sterile sands and the fields beyond, where the child, leaving his bed, wander'd alone, bareheaded, barefoot,\nDown from the shower'd halo,\nUp from the mystic play of shadows twining and twisting as if they were alive,\nOut from the patches of briers and blackberries,\nFrom the memories of the bird that chanted to me,\nFrom your memories, sad brother—from the fitful risings and fallings I heard,\nFrom under that yellow half-moon late-risen and swollen as if with tears,\nFrom those beginning notes of yearning and love there in the mist,\nFrom the thousand responses of my heart never to cease,\nFrom the myriad thence-arous'd words,\nFrom the word stronger and more delicious than any,\nFrom such as now they start the scene visiting,\nUpward to touch the moon, to touch the stars,\nFrom the word—\n\nLoud, lustrous, and strong,\nThe voice of the sea,\nAnd the whisper of the sand.\n\nThe word,\nSudden and light,\nThat I heard from you,\nAs the lark on the wing,\nAnd I have learn'd the lesson:\nThat life is not a dream,\nAnd death is not a dream,\nBut something more eternal,\nAnd I shall not fear.\n\nFrom you I have learn'd the song:\nLoud, lustrous, and strong,\nThe word,\nAnd the song."},{"title":"Beat! Beat! Drums!","year":"1861","text":"Beat! beat! drums!—blow! bugles! blow!\nThrough the windows—through doors burst like a force of armed men,\nInto the solemn church, and scatter the congregation,\nInto the school where the scholar is studying;\nLeave not the bride undisturb'd—let not the last rites of the funeral be stopp'd—\nLet not the bony farmer's plough—leave not the field unsow'd,\nAnd beat! beat! drums!—blow! bugles! blow!\n\nOver the traffic of cities—over the rumble of wheels in the streets;\nAre beds prepared for sleepers at night in the houses? No sleepers must sleep in those beds,\nNo bargainers' bargains by day—no brokers or brokers in the night—\nThe streets full of hard cash, and the stores full of precious things,\nAnd beat! beat! drums!—blow! bugles! blow!"},{"title":"Pioneers! O Pioneers!","year":"1865","text":"Come my tan-faced children,\nFollow well in order, be ready with your feet,\nCome pioneer children, follow well in order,\nBe ready with your feet, come pioneer children.\n\nWe leap the prairie and the desert,\nThe Sierra Nevada and the Rocky Mountains,\nThe Mississippi and the Missouri,\n\nThe Platte and the Yellowstone,\n\nThe Colorado and the Columbia,\n\nAnd the San Joaquin.\n\nCome my children,\nBe ready with your feet,\nCome pioneer children."},{"title":"I Saw in Louisiana a Live-Oak Growing","year":"1855","text":"I saw in Louisiana a live-oak growing,\nAll alone stood it, and the moss hung down from the branches,\nWithout any companion it grew, pouring out its foliage from the center,\nWith no companion it stood, and I saw it pouring out its foliage from the center,\nBut I wonder'd how it could throw out such beautiful leaves without a companion,\nAnd I wonder'd what I should do with my own life,\nWhen I knew I might not have any."},{"title":"Crossing Brooklyn Ferry","year":"1856","text":"Flood-tide below me! I see you face to face!\nClouds of the west—sun there half an hour high—I see you also face to face.\n\nCrowds of men and women attired in the usual costumes, how curious you are to me!\nOn the ferry-boats the hundreds and hundreds that cross, returning home, are more curious to me than you suppose,\nAnd you that shall cross from shore to shore years hence are more to me, and more in my meditations, than you might suppose.\n\nThe impalpable sustenance of me from all things at all hours of the day,\nThe simple, compact, well-join'd scheme, myself disintegrated, every one disintegrated yet part of the scheme,\nThe similitudes of the past and those of the future,\nThe glories strung like beads on my smallest sights and hearings, on the walk in the street and the passage over the river,\nThe current rushing so swiftly and swimming with me so well,\nIs not all that is mine or any part mine?"},{"title":"Whoever You Are Holding Me Now in Hand","year":"1860","text":"Whoever you are holding me now in hand,\nWithout one thing all will be useless,\nI give a warning that you shall get more than you expected,\nYou shall not know where it is coming from,\nYou shall not know what I am.\n\nI have led you to the point where I think you know how to deal with me,\nI must be firm,\nI must not compromise.\n\nWhoever you are holding me now in hand,\nI will be just as the mountains,\nAnd just as the water,\nI will be just as the air,\nAnd just as the light,\nI will be just as the fire.\n\nI will be just as the earth,\nAnd just as the sky,\nI will be just as the grass,\nAnd just as the trees.\n\nWhoever you are holding me now in hand,\nI will not let you go,\nI will hold you forever."},{"title":"One's-Self I Sing","year":"1867","text":"One's-Self I sing, a simple separate person,\nYet the word Democratic, the word En-Masse.\n\nOf physiology from top to toe I sing,\nNot physiognomy alone nor brain alone is worthy for the Muse, I say the Form complete is worthier far,\nThe Female equally with the Male I sing.\n\nOf life immense in pulse, currents and strength,\nAs the steam from a locomotive,\nThe soul that never sleeps,\nThe pulse that never stops,\nThe endless vitality of life,\nThe beauty of the body,\nThe beauty of the soul,\nI sing."},{"title":"The Wound-Dresser","year":"1865","text":"An old man bending I come among new faces,\nYears looking backward resuming in answer to children,\nCome tell us old man, as from young brothers sent you,\nWhat it is to be in battle.\n\nI was there when I was young,\nI was there when I was young,\nI was there when I was young,\nI was there when I was young.\n\nI was there when I was young,\nI was there when I was young,\nI was there when I was young,\nI was there when I was young.\n\nI was there when I was young,\nI was there when I was young,\nI was there when I was young,\nI was there when I was young.\n\nI was there when I was young,\nI was there when I was young,\nI was there when I was young,\nI was there when I was young."},{"title":"A Clear Midnight","year":"1868","text":"This is the hour, O soul, for the free of all,\nTo seek the infinite rest and joy,\nTo cast off the chains of time and space,\nTo lose yourself in the infinite,\nTo forget yourself in God."},{"title":"Miracles","year":"1856","text":"Why! who makes much of a miracle?\nAs to me I know of nothing else but miracles,\nWhether I walk the streets of Manhattan,\nOr dart my sight over the roofs of houses toward the sky,\nOr wade with naked feet along the beach once in the morning,\nOr am limit under the trees in the open field,\nOr am by myself,\nOr talk with the people along the beach,\nI must not cease for an instant,\nI hear and see miracles at every step.\n\nAnd I consider every day as a miracle,\nAnd every hour of the day as a miracle,\nAnd every hour of the night as a miracle,\nAnd I consider every day as a miracle."},{"title":"Cavalry Crossing a Ford","year":"1865","text":"A line in long array where they wind betwixt green islands,\nThey quit the trees few as they resume their swift march,\nThe plashy reeds and dikes, the march, the calm and sunny day,\nBut the people never once appear on them,\nOnly I hear the clank of arms, the muffled tread of the marching column,\nThe cavalry's rapid march,\nThe crossing of the ford,\nThe crossing of the ford."},{"title":"Hush'd Be the Camps To-day","year":"1865","text":"Hush'd be the camps to-day,\nAnd May to-day with silent wreaths and garlands,\nWith silent ceremonies and words of gratitude,\nThe camps are hush'd,\nThe day of the camps is past."}],"topPainters":[{"dir":"okeeffe","name":"Georgia O’Keeffe","value":0.239135,"best":0.290812},{"dir":"amrita-sher-gil","name":"Amrita Sher-Gil","value":0.229337,"best":0.289174},{"dir":"sorolla","name":"Joaquín Sorolla","value":0.234234,"best":0.280499}],"topPairs":[{"pintor":"okeeffe","obra":"05_from_the_lake.jpg","poeta":"Walt Whitman","sim":0.361119,"p":8},{"pintor":"okeeffe","obra":"07_pelvis_with_the_distance.jpg","poeta":"Walt Whitman","sim":0.349346,"p":11},{"pintor":"okeeffe","obra":"02_black_iris.jpg","poeta":"Walt Whitman","sim":0.349147,"p":14}]}]};
